const LEGACY_TRAINING_BANK=[{"id":"legacy-sets-1","topicId":2,"question":"Для X=(−3,4] выбери точные грани и экстремумы.","options":["sup X=4, max X=4; inf X=−3, минимума нет","sup X=4, максимума нет; inf X=−3, min X=−3","max X=4 и min X=−3"],"correct":0,"steps":[{"title":"Шаг 1","text":"Интервал (−3,4] содержит все числа между −3 и 4, причём 4 включено, а −3 исключено."},{"title":"Шаг 2","text":"Каждый x∈X удовлетворяет x≤4, поэтому 4 является верхней гранью. Так как 4∈X, это одновременно максимум и супремум."},{"title":"Шаг 3","text":"Каждый x∈X удовлетворяет x>−3, поэтому −3 — нижняя грань."},{"title":"Шаг 4","text":"Для любого ε>0 возьмём h=min(ε/2,1) и x=−3+h. Тогда x∈X и −3<x<−3+ε: никакая большая нижняя грань не подходит."},{"title":"Шаг 5","text":"Следовательно, inf X=−3. Минимума нет, потому что −3∉X, а любой допустимый x можно уменьшить, взяв (x−3)/2 между −3 и x."}],"source":"Нарешка · Множества и точные грани"},{"id":"legacy-sets-2","topicId":3,"question":"Найди sup и max множества X={2−1/n : n∈ℕ, n≥1}.","options":["sup X=2, max X=1","sup X=2, максимума нет","sup X=1, max X=1"],"correct":1,"steps":[{"title":"Шаг 1","text":"При n≥1 величина 1/n положительна, поэтому каждый элемент 2−1/n строго меньше 2."},{"title":"Шаг 2","text":"Следовательно, 2 — верхняя грань множества X. Это ещё не доказательство её точности."},{"title":"Шаг 3","text":"Для ε>0 выберем натуральное n>1/ε. Тогда 1/n<ε и 2−ε<2−1/n<2."},{"title":"Шаг 4","text":"Найдены элементы сколь угодно близко к 2 снизу, значит sup X=2."},{"title":"Шаг 5","text":"Равенство 2−1/n=2 невозможно при конечном n. Кроме того, следующий член больше предыдущего, поэтому максимума нет."}],"source":"Нарешка · Множества и точные грани"},{"id":"legacy-sets-3","topicId":3,"question":"Для X={x∈ℝ : x²<9} верно:","options":["max X=3","sup X=3, max X не существует","sup X=9"],"correct":1,"steps":[{"title":"Шаг 1","text":"Решаем x²<9: это равносильно |x|<3, то есть −3<x<3."},{"title":"Шаг 2","text":"Получаем открытый интервал X=(−3,3). Для каждого его элемента x<3, следовательно, 3 — верхняя грань."},{"title":"Шаг 3","text":"Для произвольного ε>0 выбираем h=min(ε/2,1), x=3−h. Тогда x∈X и x>3−ε."},{"title":"Шаг 4","text":"По ε-критерию точной грани sup X=3."},{"title":"Шаг 5","text":"Число 3 не входит в X, так как 3²=9 не удовлетворяет строгому условию. Любой x∈X можно увеличить до (x+3)/2∈X, поэтому максимума нет."}],"source":"Нарешка · Множества и точные грани"},{"id":"legacy-sets-4","topicId":2,"question":"Множество [1,+∞) является…","options":["ограниченным сверху и снизу","ограниченным снизу, неограниченным сверху","ограниченным сверху, неограниченным снизу"],"correct":1,"steps":[{"title":"Шаг 1","text":"Область [1,+∞) содержит 1 и все числа больше 1."},{"title":"Шаг 2","text":"Из x≥1 для всех x∈X следует, что 1 — нижняя грань. Она достигается, поэтому min X=inf X=1."},{"title":"Шаг 3","text":"Допустим, число M является верхней гранью. Тогда все допустимые x должны удовлетворять x≤M."},{"title":"Шаг 4","text":"Выберем x=max(1,M+1). Эта точка лежит в X и превышает M, что противоречит верхней оценке."},{"title":"Шаг 5","text":"Таким образом, множество ограничено снизу и неограниченно сверху. Наличие одного конечного края не означает ограниченности с обеих сторон."}],"source":"Нарешка · Множества и точные грани"},{"id":"legacy-sets-5","topicId":3,"question":"Пусть X=(0,1). Какое утверждение доказывает sup X=1?","options":["1∈X","x≤1 для всех x∈X, и для каждого ε>0 есть x∈X с 1−ε<x","каждый x∈X строго меньше 1"],"correct":1,"steps":[{"title":"Шаг 1","text":"Число s является супремумом, если оно верхняя грань и ни одно меньшее число верхней гранью не является."},{"title":"Шаг 2","text":"Для X=(0,1) первая часть проверяется сразу: каждый элемент x<1, а значит x≤1."},{"title":"Шаг 3","text":"Чтобы проверить вторую часть, возьмём любое ε>0 и x=1−min(ε/2,1/2). Тогда 0<x<1 и 1−ε<x."},{"title":"Шаг 4","text":"Следовательно, любое число c<1 не является верхней гранью: при ε=1−c найдётся элемент x>c."},{"title":"Шаг 5","text":"Итак, верно сочетание двух условий «x≤1 для всех x» и «для каждого ε>0 найдётся x>1−ε». Одного из этих условий недостаточно."}],"source":"Нарешка · Множества и точные грани"},{"id":"legacy-sets-6","topicId":3,"question":"Найди inf X для X={1/n : n∈ℕ}.","options":["0, и минимума нет","1, это минимум","−1"],"correct":0,"steps":[{"title":"Шаг 1","text":"Каждый элемент 1/n при натуральном n положителен. Поэтому 0 — нижняя грань X."},{"title":"Шаг 2","text":"Для ε>0 выбираем натуральное n>1/ε. Тогда 0<1/n<ε."},{"title":"Шаг 3","text":"Это означает, что элементы X подходят к нулю сверху сколь угодно близко. Следовательно, inf X=0."},{"title":"Шаг 4","text":"Нуль не имеет вида 1/n при конечном n, поэтому он не принадлежит X."},{"title":"Шаг 5","text":"Минимума нет: для каждого элемента 1/n следующий элемент 1/(n+1) меньше и также находится в X."}],"source":"Нарешка · Множества и точные грани"},{"id":"legacy-sets-7","topicId":2,"question":"Для X={−2,0,5} выбери верное.","options":["sup X=5 и max X=5","sup X=5, max не существует","sup X=0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Перечислены три элемента: −2,0 и 5. Сравним их по обычному порядку чисел."},{"title":"Шаг 2","text":"Все элементы не превосходят 5, поэтому 5 — верхняя грань."},{"title":"Шаг 3","text":"Элемент 5 входит в X, следовательно, любая верхняя грань должна быть не меньше 5."},{"title":"Шаг 4","text":"Таким образом, 5 — наименьшая верхняя грань, то есть sup X=5; так как она достигается, max X=5."},{"title":"Шаг 5","text":"Аналогично −2 является минимумом и инфимумом. Для конечного непустого множества оба экстремума всегда существуют."}],"source":"Нарешка · Множества и точные грани"},{"id":"legacy-sets-8","topicId":2,"question":"Если A — верхняя грань X, то…","options":["любое A′>A тоже верхняя грань","любое A′<A верхняя грань","A обязательно принадлежит X"],"correct":0,"steps":[{"title":"Шаг 1","text":"По условию A — верхняя грань, то есть для каждого x∈X имеем x≤A."},{"title":"Шаг 2","text":"Берём любое A′>A. Для каждого x получаем цепочку x≤A<A′."},{"title":"Шаг 3","text":"В частности, x≤A′ для всех x∈X. Это в точности определение верхней грани A′."},{"title":"Шаг 4","text":"Значит, повышение верхней грани сохраняет свойство быть верхней гранью."},{"title":"Шаг 5","text":"Обратное неверно: если X={1}, то A=1 — верхняя грань, а меньшее число 0 уже не подходит. Верхняя грань не обязана быть точной."}],"source":"Нарешка · Множества и точные грани"},{"id":"legacy-seq-1","topicId":6,"question":"Что значит lim xₙ=a?","options":["∀ε>0 ∃N: при всех n>N выполняется |xₙ−a|<ε","∃ε>0 ∀n: |xₙ−a|<ε","xₙ=a для всех n"],"correct":0,"steps":[{"title":"Шаг 1","text":"Предел a означает близость всех достаточно поздних членов к a при любой заранее заданной точности."},{"title":"Шаг 2","text":"Сначала берём произвольное ε>0. Оно задаёт разрешённое расстояние |xₙ−a|."},{"title":"Шаг 3","text":"После этого подбираем N, который может зависеть от ε. Требование относится ко всем n>N, а не к одному удачному номеру."},{"title":"Шаг 4","text":"Получаем запись ∀ε>0 ∃N ∀n>N: |xₙ−a|<ε. Начальные N членов могут находиться далеко от a."},{"title":"Шаг 5","text":"Если поменять порядок на ∃N∀ε, пришлось бы одним хвостом обеспечить сразу любую точность, что является существенно более сильным условием."}],"source":"Нарешка · Предел последовательности"},{"id":"legacy-seq-2","topicId":13,"question":"Найди limₙ→∞ (3n+1)/(n+2).","options":["0","1","3"],"correct":2,"steps":[{"title":"Шаг 1","text":"Подстановка «n=∞» не является арифметической операцией. Нужно преобразовать дробь для больших конечных n."},{"title":"Шаг 2","text":"Делим числитель и знаменатель на n: (3n+1)/(n+2)=(3+1/n)/(1+2/n)."},{"title":"Шаг 3","text":"При n→∞ имеем 1/n→0 и 2/n→0. Поэтому числитель стремится к 3, а знаменатель — к 1."},{"title":"Шаг 4","text":"Так как предел знаменателя ненулевой, применяем правило частного и получаем 3/1=3."},{"title":"Шаг 5","text":"Проверка по определению: дробь минус 3 равна −5/(n+2). Её модуль 5/(n+2) меньше ε при n>5/ε, что подтверждает предел."}],"source":"Нарешка · Предел последовательности"},{"id":"legacy-seq-3","topicId":6,"question":"Какой N достаточно выбрать в доказательстве 1/n→0 для ε=0,01?","options":["N=10","N=100","N=1"],"correct":1,"steps":[{"title":"Шаг 1","text":"Для последовательности xₙ=1/n и кандидата a=0 расстояние равно |xₙ−a|=1/n."},{"title":"Шаг 2","text":"При ε=0,01=1/100 требуется строгое неравенство 1/n<1/100."},{"title":"Шаг 3","text":"Так как n положительно, это равносильно n>100."},{"title":"Шаг 4","text":"В определении используются номера n>N, поэтому выбор N=100 обеспечивает нужное условие для каждого последующего n."},{"title":"Шаг 5","text":"Не требуется неравенства при n=N: там было бы равенство 1/100=ε. Если использовать соглашение n≥N, понадобился бы N=101."}],"source":"Нарешка · Предел последовательности"},{"id":"legacy-seq-4","topicId":6,"question":"Последовательность (−1)ⁿ…","options":["сходится к 0","сходится к 1","не имеет предела; имеет две предельные точки"],"correct":2,"steps":[{"title":"Шаг 1","text":"Для чётного n=2k имеем (−1)ⁿ=1. Для нечётного n=2k−1 имеем (−1)ⁿ=−1."},{"title":"Шаг 2","text":"Чётная подпоследовательность постоянно равна 1 и сходится к 1. Нечётная постоянно равна −1 и сходится к −1."},{"title":"Шаг 3","text":"Если бы вся последовательность имела предел a, обе подпоследовательности должны были бы сходиться к тому же a."},{"title":"Шаг 4","text":"Но 1≠−1. Поэтому общего предела нет, а оба числа являются предельными точками."},{"title":"Шаг 5","text":"Других предельных точек нет: любой член принимает только одно из этих двух значений, и окрестность любого другого числа можно выбрать не содержащей ни 1, ни −1."}],"source":"Нарешка · Предел последовательности"},{"id":"legacy-seq-5","topicId":7,"question":"Если xₙ→a, то последовательность…","options":["обязательно ограничена","обязательно монотонна","обязательно положительна"],"correct":0,"steps":[{"title":"Шаг 1","text":"По условию xₙ→a. Используем определение с точностью ε=1."},{"title":"Шаг 2","text":"Найдётся N, после которого |xₙ−a|<1. По треугольнику |xₙ|≤|a|+|xₙ−a|<|a|+1."},{"title":"Шаг 3","text":"Оставшиеся члены x₁,…,x_N образуют конечный набор. Их модули имеют конечный максимум B."},{"title":"Шаг 4","text":"Положим M=max(B,|a|+1). Тогда и начальные члены, и весь хвост удовлетворяют |xₙ|≤M."},{"title":"Шаг 5","text":"Это доказывает ограниченность всей последовательности. Монотонность, положительность и достижение предела из сходимости не следуют."}],"source":"Нарешка · Предел последовательности"},{"id":"legacy-seq-6","topicId":13,"question":"Последовательность 5+1/n имеет предел…","options":["0","1","5"],"correct":2,"steps":[{"title":"Шаг 1","text":"Представим xₙ=5+1/n как сумму постоянной последовательности и бесконечно малой."},{"title":"Шаг 2","text":"Постоянная последовательность 5 имеет предел 5. Последовательность 1/n имеет предел 0."},{"title":"Шаг 3","text":"По правилу суммы lim(5+1/n)=5+0=5."},{"title":"Шаг 4","text":"Прямая проверка: |(5+1/n)−5|=1/n. Для каждого ε>0 достаточно выбрать N>1/ε."},{"title":"Шаг 5","text":"Все члены больше 5 и постепенно приближаются к нему сверху. Это не означает, что какой-либо конечный член точно равен 5."}],"source":"Нарешка · Предел последовательности"},{"id":"legacy-seq-7","topicId":11,"question":"У какой последовательности предел 0?","options":["n/(n+1)","1/√n","(−1)ⁿ"],"correct":1,"steps":[{"title":"Шаг 1","text":"Для кандидата 1/√n проверим определение предела 0: модуль самого члена должен стать меньше любой ε>0."},{"title":"Шаг 2","text":"Неравенство 1/√n<ε равносильно √n>1/ε, а затем n>1/ε²."},{"title":"Шаг 3","text":"Выбираем натуральное N>1/ε². Тогда для каждого n>N нужное условие выполнено, следовательно, 1/√n→0."},{"title":"Шаг 4","text":"У варианта n/(n+1) имеем n/(n+1)=1−1/(n+1)→1, а не 0."},{"title":"Шаг 5","text":"Вариант (−1)ⁿ имеет подпоследовательности со значениями 1 и −1, поэтому вообще не сходится. Подходит только 1/√n."}],"source":"Нарешка · Предел последовательности"},{"id":"legacy-seq-8","topicId":6,"question":"Если у последовательности есть два разных предела a≠b, то…","options":["это возможно","это невозможно: предел единственен","оба предела равны 0"],"correct":1,"steps":[{"title":"Шаг 1","text":"Предположим, что xₙ→a и xₙ→b при a≠b. Обозначим d=|a−b|>0."},{"title":"Шаг 2","text":"Возьмём ε=d/3. По первому пределу существует N₁ с |xₙ−a|<d/3 при n>N₁."},{"title":"Шаг 3","text":"По второму пределу существует N₂ с |xₙ−b|<d/3 при n>N₂. Берём n>max(N₁,N₂), чтобы действовали обе оценки."},{"title":"Шаг 4","text":"Неравенство треугольника даёт d=|a−b|≤|a−xₙ|+|xₙ−b|<2d/3."},{"title":"Шаг 5","text":"Положительное d не может быть меньше 2d/3. Предположение a≠b неверно, поэтому предел единственен."}],"source":"Нарешка · Предел последовательности"},{"id":"legacy-seqops-1","topicId":13,"question":"Если xₙ→2 и yₙ→−5, чему равен lim(xₙ+yₙ)?","options":["−3","7","−10"],"correct":0,"steps":[{"title":"Шаг 1","text":"Даны конечные пределы xₙ→2 и yₙ→−5. Поэтому правило сложения пределов применимо без дополнительных условий на знаменатель."},{"title":"Шаг 2","text":"Получаем lim(xₙ+yₙ)=2+(−5)."},{"title":"Шаг 3","text":"Складываем числа с разными знаками: 2−5=−3."},{"title":"Шаг 4","text":"Проверка по определению: |xₙ+yₙ+3|≤|xₙ−2|+|yₙ+5|."},{"title":"Шаг 5","text":"Для точности ε выбираем хвост, где оба слагаемых справа меньше ε/2. Тогда сумма меньше ε, что подтверждает предел −3."}],"source":"Нарешка · Арифметика пределов и оценки"},{"id":"legacy-seqops-2","topicId":13,"question":"Вычисли lim (4n²+3)/(2n²−n).","options":["2","4","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Старшая степень и в числителе, и в знаменателе — n². Делим на неё обе части дроби."},{"title":"Шаг 2","text":"Получаем (4n²+3)/(2n²−n)=(4+3/n²)/(2−1/n)."},{"title":"Шаг 3","text":"При n→∞ величины 3/n² и 1/n стремятся к нулю."},{"title":"Шаг 4","text":"Числитель стремится к 4, знаменатель к 2≠0. Поэтому правило частного даёт предел 4/2=2."},{"title":"Шаг 5","text":"Проверка: исходная дробь минус 2 равна (2n+3)/(2n²−n), что после деления на n² стремится к 0."}],"source":"Нарешка · Арифметика пределов и оценки"},{"id":"legacy-seqops-3","topicId":13,"question":"Если xₙ→3, то lim (xₙ²−1)=…","options":["2","8","9"],"correct":1,"steps":[{"title":"Шаг 1","text":"Из xₙ→3 следует, что обе копии последовательности xₙ имеют конечный предел 3."},{"title":"Шаг 2","text":"По правилу произведения xₙ²=xₙ·xₙ→3·3=9."},{"title":"Шаг 3","text":"Постоянная последовательность 1 имеет предел 1, поэтому xₙ²−1→9−1=8."},{"title":"Шаг 4","text":"Можно проверить разность с ответом: (xₙ²−1)−8=xₙ²−9=(xₙ−3)(xₙ+3)."},{"title":"Шаг 5","text":"Первый множитель стремится к нулю, второй — к 6 и потому ограничен. Их произведение стремится к нулю, что подтверждает ответ 8."}],"source":"Нарешка · Арифметика пределов и оценки"},{"id":"legacy-seqops-4","topicId":13,"question":"Вычисли lim (n+1)/(3n−2).","options":["3","1/3","0"],"correct":1,"steps":[{"title":"Шаг 1","text":"Числитель и знаменатель имеют первую степень n. Для натуральных n≥1 знаменатель 3n−2 ненулевой."},{"title":"Шаг 2","text":"Делим обе части дроби на n: (n+1)/(3n−2)=(1+1/n)/(3−2/n)."},{"title":"Шаг 3","text":"При n→∞ числитель стремится к 1, знаменатель — к 3."},{"title":"Шаг 4","text":"Так как 3≠0, предел дроби равен 1/3."},{"title":"Шаг 5","text":"Проверка коэффициентов: отношение старших членов равно n/(3n)=1/3. Ответ 3 получился бы при обращении этой дроби."}],"source":"Нарешка · Арифметика пределов и оценки"},{"id":"legacy-seqops-5","topicId":10,"question":"Если xₙ≤zₙ≤yₙ и обе границы стремятся к 4, то…","options":["zₙ→4","zₙ→0","о zₙ ничего нельзя сказать"],"correct":0,"steps":[{"title":"Шаг 1","text":"Дано xₙ≤zₙ≤yₙ и xₙ→4,yₙ→4. Нужно показать близость zₙ к 4 с двух сторон."},{"title":"Шаг 2","text":"Для ε>0 из первого предела выбираем N₁, после которого 4−ε<xₙ."},{"title":"Шаг 3","text":"Из второго предела выбираем N₂, после которого yₙ<4+ε."},{"title":"Шаг 4","text":"Для n>max(N₁,N₂) имеем 4−ε<xₙ≤zₙ≤yₙ<4+ε."},{"title":"Шаг 5","text":"Отсюда |zₙ−4|<ε, то есть zₙ→4. Важен общий предел обеих границ; одной сходящейся границы недостаточно."}],"source":"Нарешка · Арифметика пределов и оценки"},{"id":"legacy-seqops-6","topicId":9,"question":"Если aₙ<bₙ для всех n и aₙ→2, bₙ→2, то…","options":["2<2 в пределе","пределы равны 2","предел bₙ не существует"],"correct":1,"steps":[{"title":"Шаг 1","text":"Условие aₙ<bₙ относится к каждому конечному номеру, но не требует положительной нижней границы разности."},{"title":"Шаг 2","text":"По арифметике пределов bₙ−aₙ→2−2=0."},{"title":"Шаг 3","text":"Положительные разности могут стремиться к нулю, поэтому строгий порядок членов не запрещает равенства пределов."},{"title":"Шаг 4","text":"Конкретный пример: aₙ=2−1/n, bₙ=2+1/n. Для каждого n имеем aₙ<bₙ, а обе последовательности стремятся к 2."},{"title":"Шаг 5","text":"Следовательно, указанные в условии пределы равны 2. При переходе к пределу в общем случае сохраняют знак ≤, а не обязательно <."}],"source":"Нарешка · Арифметика пределов и оценки"},{"id":"legacy-seqops-7","topicId":12,"question":"lim (1/n + 1/n²)=…","options":["1","0","не существует"],"correct":1,"steps":[{"title":"Шаг 1","text":"Первое слагаемое 1/n стремится к 0 по определению бесконечно малой последовательности."},{"title":"Шаг 2","text":"Для второго слагаемого при n>1/√ε имеем 1/n²<ε, поэтому оно тоже бесконечно мало непосредственно по определению."},{"title":"Шаг 3","text":"По правилу суммы предел равен 0+0=0."},{"title":"Шаг 4","text":"Прямая оценка: при n≥1 выполняется 0≤1/n+1/n²≤2/n."},{"title":"Шаг 5","text":"Для ε>0 достаточно n>2/ε. Тогда вся сумма меньше ε, что отдельно доказывает ответ."}],"source":"Нарешка · Арифметика пределов и оценки"},{"id":"legacy-seqops-8","topicId":13,"question":"Когда правило частного гарантированно применимо?","options":["Предел знаменателя равен 0","Предел знаменателя отличен от 0","Числитель и знаменатель неограничены"],"correct":1,"steps":[{"title":"Шаг 1","text":"Для правила частного предполагаются конечные пределы числителя xₙ→a и знаменателя yₙ→b."},{"title":"Шаг 2","text":"Нужно дополнительно b≠0. Из |yₙ−b|<|b|/2 в хвосте следует |yₙ|>|b|/2>0."},{"title":"Шаг 3","text":"Поэтому дробь в хвосте определена, а обратные знаменатели ограничены: 1/|yₙ|<2/|b|."},{"title":"Шаг 4","text":"Тогда xₙ/yₙ→a/b по арифметике пределов. Ненулевой предел обеспечивает контроль деления."},{"title":"Шаг 5","text":"При b=0 единого правила ответа нет: (1/n)/(1/n)=1, (1/n²)/(1/n)→0, а 1/(1/n)→∞. Такую форму нужно исследовать отдельно."}],"source":"Нарешка · Арифметика пределов и оценки"},{"id":"legacy-monotone-1","topicId":14,"question":"Какая теорема гарантирует сходимость?","options":["Неубывающая и ограниченная сверху","Любая возрастающая","Ограниченная снизу и неубывающая"],"correct":0,"steps":[{"title":"Шаг 1","text":"Теорема требует два свойства одновременно: неубывание и ограниченность сверху."},{"title":"Шаг 2","text":"Пусть a=sup{xₙ}. По верхней грани каждый член удовлетворяет xₙ≤a."},{"title":"Шаг 3","text":"Для ε>0 по точности sup найдётся член x_N>a−ε."},{"title":"Шаг 4","text":"По неубыванию все последующие xₙ≥x_N>a−ε. Вместе с верхней гранью получаем a−ε<xₙ≤a."},{"title":"Шаг 5","text":"Следовательно, |xₙ−a|<ε в хвосте и xₙ→a. Неубывание без верхней грани допускает уход к +∞, а ограниченность без монотонности допускает колебания."}],"source":"Нарешка · Монотонность и критерии сходимости"},{"id":"legacy-monotone-2","topicId":14,"question":"Последовательность xₙ=−n…","options":["убывает и ограничена снизу","убывает, не ограничена снизу","возрастает"],"correct":1,"steps":[{"title":"Шаг 1","text":"Вычисляем разность соседних членов: xₙ₊₁−xₙ=−(n+1)−(−n)=−1<0."},{"title":"Шаг 2","text":"Значит, последовательность строго убывает."},{"title":"Шаг 3","text":"Для любого M>0 выбираем n>M. Тогда xₙ=−n<−M, поэтому конечной нижней грани нет."},{"title":"Шаг 4","text":"Все члены при n≥1 удовлетворяют xₙ≤−1, так что сверху последовательность ограничена."},{"title":"Шаг 5","text":"Для каждого порога M весь хвост n>M лежит ниже −M; это также доказывает xₙ→−∞. Конечного предела нет."}],"source":"Нарешка · Монотонность и критерии сходимости"},{"id":"legacy-monotone-3","topicId":18,"question":"Критерий Коши сравнивает…","options":["члены с предполагаемым пределом","два произвольных достаточно поздних члена","первый и последний член"],"correct":1,"steps":[{"title":"Шаг 1","text":"Критерий Коши не требует заранее угадать значение предела a."},{"title":"Шаг 2","text":"Для заданной ε>0 он требует найти N, после которого любые два члена будут близки друг к другу."},{"title":"Шаг 3","text":"Формальная запись: ∀ε>0 ∃N ∀m,n>N: |xₘ−xₙ|<ε."},{"title":"Шаг 4","text":"Слова «любые два» важны: условие только для соседей |xₙ₊₁−xₙ|→0 недостаточно, как показывают гармонические суммы."},{"title":"Шаг 5","text":"В ℝ этот критерий равносилен существованию конечного предела. Значит, сравниваются два произвольных достаточно поздних члена."}],"source":"Нарешка · Монотонность и критерии сходимости"},{"id":"legacy-monotone-4","topicId":17,"question":"Что утверждает теорема Больцано—Вейерштрасса?","options":["Любая ограниченная последовательность сходится","Из ограниченной можно выделить сходящуюся подпоследовательность","Любая последовательность монотонна"],"correct":1,"steps":[{"title":"Шаг 1","text":"Гипотеза теоремы Больцано–Вейерштрасса — ограниченность вещественной последовательности."},{"title":"Шаг 2","text":"Она гарантирует существование строго возрастающих индексов n₁<n₂<… и числа a∈ℝ, для которых xₙₖ→a."},{"title":"Шаг 3","text":"Это утверждение об одной выделенной подпоследовательности, а не обо всём исходном наборе членов."},{"title":"Шаг 4","text":"Например, (−1)ⁿ ограничена и имеет постоянную чётную подпоследовательность с пределом 1, хотя вся не сходится."},{"title":"Шаг 5","text":"Ни монотонность, ни единственность предельной точки теорема не обещает. Верен вариант о возможности выделить сходящуюся подпоследовательность."}],"source":"Нарешка · Монотонность и критерии сходимости"},{"id":"legacy-monotone-5","topicId":14,"question":"xₙ=1−1/n при n≥1…","options":["убывает к 0","возрастает к 1","возрастает к 0"],"correct":1,"steps":[{"title":"Шаг 1","text":"Вычисляем xₙ₊₁−xₙ=1/n−1/(n+1)=1/[n(n+1)]>0. Значит, последовательность возрастает."},{"title":"Шаг 2","text":"Поскольку 1/n>0, для каждого n выполняется xₙ=1−1/n<1. Число 1 — верхняя грань."},{"title":"Шаг 3","text":"По теореме о монотонной ограниченной последовательности конечный предел существует."},{"title":"Шаг 4","text":"Для ε>0 выбираем N>1/ε. При n>N имеем |xₙ−1|=1/n<ε."},{"title":"Шаг 5","text":"Следовательно, xₙ возрастает к 1. Значение 1 не достигается ни при одном конечном n."}],"source":"Нарешка · Монотонность и критерии сходимости"},{"id":"legacy-monotone-6","topicId":14,"question":"Если последовательность неубывает и sup её членов равен 6, то предел…","options":["0","6","не существует"],"correct":1,"steps":[{"title":"Шаг 1","text":"Пусть a=6 — супремум множества всех членов. Тогда xₙ≤6 для каждого n."},{"title":"Шаг 2","text":"Для ε>0 по определению точной грани существует номер N с x_N>6−ε."},{"title":"Шаг 3","text":"Так как последовательность неубывает, для каждого n≥N имеем xₙ≥x_N>6−ε."},{"title":"Шаг 4","text":"Получаем 6−ε<xₙ≤6, то есть |xₙ−6|<ε в хвосте."},{"title":"Шаг 5","text":"Это доказывает предел 6 независимо от того, достигается ли супремум каким-либо членом."}],"source":"Нарешка · Монотонность и критерии сходимости"},{"id":"legacy-monotone-7","topicId":17,"question":"Может ли ограниченная последовательность не иметь предела?","options":["нет","да, например (−1)ⁿ","нет, если она содержит 0"],"correct":1,"steps":[{"title":"Шаг 1","text":"Рассмотрим последовательность xₙ=(−1)ⁿ. Её модуль для каждого n равен 1, так что она ограничена."},{"title":"Шаг 2","text":"Чётные члены x₂ₖ=1 имеют предел 1."},{"title":"Шаг 3","text":"Нечётные члены x₂ₖ₋₁=−1 имеют предел −1."},{"title":"Шаг 4","text":"Если бы вся последовательность сходилась, оба этих предела должны были бы совпадать с её единственным пределом."},{"title":"Шаг 5","text":"Так как 1≠−1, сходимости нет. Ограниченность даёт лишь существование сходящейся подпоследовательности, а не сходимость всей последовательности."}],"source":"Нарешка · Монотонность и критерии сходимости"},{"id":"legacy-monotone-8","topicId":14,"question":"Что обязательно нужно сделать до подстановки предела в рекуррентное равенство?","options":["доказать существование предела","предположить предел равен 0","проверить только первый член"],"correct":0,"steps":[{"title":"Шаг 1","text":"Рекуррентное равенство связывает соседние члены, например xₙ₊₁=F(xₙ), но само по себе не доказывает существование предела."},{"title":"Шаг 2","text":"Сначала устанавливают сходимость: часто доказывают монотонность и нужную одностороннюю ограниченность."},{"title":"Шаг 3","text":"После этого обозначают фактически существующий предел a и проверяют непрерывность F в a либо иной законный переход к пределу."},{"title":"Шаг 4","text":"Только теперь из xₙ₊₁=F(xₙ) можно вывести a=F(a). Это уравнение определяет кандидатов на уже доказанный предел."},{"title":"Шаг 5","text":"Контрпример к преждевременной подстановке: xₙ₊₁=−xₙ при x₁=1 даёт уравнение a=−a с корнем 0, но сама последовательность 1,−1,1,−1,… не сходится."}],"source":"Нарешка · Монотонность и критерии сходимости"},{"id":"legacy-functionlim-1","topicId":19,"question":"В определении предела f при x→x₀ почему исключено x=x₀?","options":["значение функции в самой точке не влияет на предел","функция обязана быть отрицательной","предел считается только для целых x"],"correct":0,"steps":[{"title":"Шаг 1","text":"Предел при x→x₀ описывает значения в точках, приближающихся к x₀, а не отдельное значение в самой точке."},{"title":"Шаг 2","text":"По Коши проверяют 0<|x−x₀|<δ. Левая строгая часть исключает x=x₀."},{"title":"Шаг 3","text":"Изменение или удаление одного значения f(x₀) не меняет ни одну из проверяемых оценок."},{"title":"Шаг 4","text":"Например, f(x)=7 при x≠0 имеет предел 7 в нуле, каково бы ни было f(0)."},{"title":"Шаг 5","text":"Для непрерывности уже требуется дополнительное равенство предела значению f(x₀). Поэтому исключение точки отделяет понятие предела от непрерывности."}],"source":"Нарешка · Предел функции: Коши и Гейне"},{"id":"legacy-functionlim-2","topicId":21,"question":"limₓ→2 (x²−4)/(x−2) равен…","options":["0","2","4"],"correct":2,"steps":[{"title":"Шаг 1","text":"При x=2 исходная дробь даёт 0/0, то есть прямой подстановкой ответ получить нельзя."},{"title":"Шаг 2","text":"Раскладываем разность квадратов: x²−4=(x−2)(x+2)."},{"title":"Шаг 3","text":"При x≠2 сокращаем ненулевой множитель x−2. На проколотой окрестности дробь равна x+2."},{"title":"Шаг 4","text":"Функция x+2 непрерывна, поэтому её предел при x→2 равен 4."},{"title":"Шаг 5","text":"Сокращение законно именно при x≠2, что согласуется с определением предела. Неопределённость исходного значения в самой точке ответу не мешает."}],"source":"Нарешка · Предел функции: Коши и Гейне"},{"id":"legacy-functionlim-3","topicId":38,"question":"Для доказательства lim x²=9 при x→3 начинаем с…","options":["|x²−9|=|x−3||x+3|","x²−9=0 для всех x","δ=ε всегда"],"correct":0,"steps":[{"title":"Шаг 1","text":"Для доказательства предела 9 требуется сделать |x²−9| меньше любой заданной ε>0."},{"title":"Шаг 2","text":"Разложение даёт |x²−9|=|x−3||x+3|. Оно выделяет малый множитель |x−3|."},{"title":"Шаг 3","text":"Дополнительно потребуем |x−3|<1. Тогда 2<x<4 и |x+3|<7."},{"title":"Шаг 4","text":"Получаем |x²−9|<7|x−3|. Поэтому выбираем δ=min(1,ε/7)."},{"title":"Шаг 5","text":"Если 0<|x−3|<δ, то |x²−9|<7δ≤ε. Нужная начальная формула — произведение |x−3||x+3|, а ограничение второго множителя завершает доказательство."}],"source":"Нарешка · Предел функции: Коши и Гейне"},{"id":"legacy-functionlim-4","topicId":39,"question":"Как показать, что предела нет, используя Гейне?","options":["Найти две последовательности xₙ→x₀ с разными пределами f(xₙ)","Проверить только значение f(x₀)","Показать, что f ограничена"],"correct":0,"steps":[{"title":"Шаг 1","text":"По определению Гейне существование предела A требует f(xₙ)→A для любой допустимой последовательности xₙ→x₀ с xₙ≠x₀."},{"title":"Шаг 2","text":"Выбираем две такие последовательности xₙ и yₙ, обе из области функции."},{"title":"Шаг 3","text":"Вычисляем пределы f(xₙ)→B и f(yₙ)→C."},{"title":"Шаг 4","text":"Если B≠C, общего A быть не может: один предел не равен двум разным числам."},{"title":"Шаг 5","text":"Поэтому достаточно двух путей с различными пределами значений. Просто две разные последовательности без вычисления значений ещё ничего не доказывают."}],"source":"Нарешка · Предел функции: Коши и Гейне"},{"id":"legacy-functionlim-5","topicId":19,"question":"У f(x)=7 при x≠0 и f(0)=−100 предел при x→0 равен…","options":["−100","7","не существует"],"correct":1,"steps":[{"title":"Шаг 1","text":"Во всех точках проколотой окрестности нуля функция равна 7."},{"title":"Шаг 2","text":"Для кандидата A=7 имеем |f(x)−7|=0 при каждом x≠0."},{"title":"Шаг 3","text":"Для любого ε>0 можно взять любое δ>0: из 0<|x|<δ автоматически следует 0<ε для нужной ошибки 0."},{"title":"Шаг 4","text":"Следовательно, lim при x→0 f(x)=7. Значение f(0)=−100 в эту проверку не входит."},{"title":"Шаг 5","text":"Функция при этом не непрерывна в 0, поскольку её значение −100 не совпадает с пределом 7."}],"source":"Нарешка · Предел функции: Коши и Гейне"},{"id":"legacy-functionlim-6","topicId":38,"question":"limₓ→1 (3x+2) равен…","options":["3","5","2"],"correct":1,"steps":[{"title":"Шаг 1","text":"Линейная функция 3x+2 непрерывна на ℝ, поэтому кандидат предела в точке 1 равен 3·1+2=5."},{"title":"Шаг 2","text":"Проверим его по определению: |(3x+2)−5|=3|x−1|."},{"title":"Шаг 3","text":"Для произвольного ε>0 выбираем δ=ε/3, которое положительно."},{"title":"Шаг 4","text":"При 0<|x−1|<δ имеем |(3x+2)−5|=3|x−1|<3δ=ε."},{"title":"Шаг 5","text":"Определение выполнено для всех точек проколотой окрестности. Ответ равен 5."}],"source":"Нарешка · Предел функции: Коши и Гейне"},{"id":"legacy-functionlim-7","topicId":39,"question":"У f(x)=sin(1/x) при x→0 предел…","options":["0","1","не существует"],"correct":2,"steps":[{"title":"Шаг 1","text":"Выберем xₙ=1/(π/2+2πn) и yₙ=1/(3π/2+2πn). Обе последовательности ненулевые и стремятся к 0."},{"title":"Шаг 2","text":"Для первой sin(1/xₙ)=sin(π/2+2πn)=1."},{"title":"Шаг 3","text":"Для второй sin(1/yₙ)=sin(3π/2+2πn)=−1."},{"title":"Шаг 4","text":"По Гейне общий предел функции потребовал бы одинакового предела значений вдоль обеих последовательностей."},{"title":"Шаг 5","text":"Но 1≠−1, поэтому предел не существует. Ограниченность синуса не устраняет колебания с постоянной амплитудой."}],"source":"Нарешка · Предел функции: Коши и Гейне"},{"id":"legacy-functionlim-8","topicId":21,"question":"Если lim f(x)=2 и lim g(x)=−1, то lim(fg)=…","options":["1","−2","2"],"correct":1,"steps":[{"title":"Шаг 1","text":"Даны два конечных предела при одном и том же приближении аргумента: f→2 и g→−1."},{"title":"Шаг 2","text":"По теореме о произведении пределов fg→2·(−1)=−2."},{"title":"Шаг 3","text":"Разложим ошибку для проверки: fg+2=f(g+1)−(f−2)."},{"title":"Шаг 4","text":"Из f→2 следует локальная ограниченность f. Оба выражения g+1 и f−2 стремятся к нулю."},{"title":"Шаг 5","text":"Поэтому оба слагаемых ошибки стремятся к нулю, что подтверждает ответ −2. Для произведения не нужно условие ненулевого предела множителя."}],"source":"Нарешка · Предел функции: Коши и Гейне"},{"id":"legacy-onesided-1","topicId":35,"question":"Для f(x)=|x|/x при x→0 односторонние пределы равны…","options":["слева 1, справа −1","слева −1, справа 1","оба 0"],"correct":1,"steps":[{"title":"Шаг 1","text":"Справа от нуля x>0, поэтому |x|=x и |x|/x=1."},{"title":"Шаг 2","text":"Следовательно, правый предел равен 1 как предел постоянной функции на положительной полуокрестности."},{"title":"Шаг 3","text":"Слева x<0, поэтому |x|=−x и |x|/x=−1."},{"title":"Шаг 4","text":"Левый предел равен −1. Значение в самом нуле не используется и дробь там не определена."},{"title":"Шаг 5","text":"Итак, слева −1, справа 1. Общего двустороннего предела нет, поскольку односторонние значения различаются."}],"source":"Нарешка · Односторонние пределы и критерий Коши"},{"id":"legacy-onesided-2","topicId":35,"question":"Двусторонний предел существует, если…","options":["существует хотя бы один односторонний предел","оба односторонних предела конечны и равны","функция определена в x₀"],"correct":1,"steps":[{"title":"Шаг 1","text":"Для существования конечного двустороннего предела A необходимо, чтобы оба конечных односторонних предела существовали и равнялись A."},{"title":"Шаг 2","text":"Необходимость следует из ограничения общего определения сначала на x<x₀, затем на x>x₀."},{"title":"Шаг 3","text":"Обратно, пусть оба предела равны A. Для ε>0 получаем левый радиус δ₋ и правый δ₊ с нужными оценками."},{"title":"Шаг 4","text":"Берём δ=min(δ₋,δ₊). Любой x с 0<|x−x₀|<δ лежит либо слева, либо справа и удовлетворяет соответствующей оценке |f(x)−A|<ε."},{"title":"Шаг 5","text":"Это даёт двусторонний предел A. Речь в выбранном ответе идёт о конечном пределе; совпадающие бесконечные односторонние пределы дают соответствующий расширенный предел."}],"source":"Нарешка · Односторонние пределы и критерий Коши"},{"id":"legacy-onesided-3","topicId":28,"question":"f(x)=1/x при x→0⁺ стремится к…","options":["+∞","−∞","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"При x→0⁺ рассматриваются только положительные x, поэтому 1/x положительно."},{"title":"Шаг 2","text":"Чтобы доказать уход к +∞, для каждого M>0 нужно обеспечить 1/x>M в достаточно малой правой окрестности."},{"title":"Шаг 3","text":"Для x>0 неравенство 1/x>M равносильно x<1/M."},{"title":"Шаг 4","text":"Выбираем δ=1/M. Тогда из 0<x<δ следует 1/x>M."},{"title":"Шаг 5","text":"Определение бесконечного правого предела выполнено. Поэтому ответ +∞; знак определяется положительной стороной приближения."}],"source":"Нарешка · Односторонние пределы и критерий Коши"},{"id":"legacy-onesided-4","topicId":35,"question":"У f(x)=sgn(x) в 0 есть двусторонний предел?","options":["да, равен 0","да, равен 1","нет: односторонние пределы разные"],"correct":2,"steps":[{"title":"Шаг 1","text":"Функция sgn x равна −1 при x<0 и 1 при x>0."},{"title":"Шаг 2","text":"В левой полуокрестности она постоянна, поэтому левый предел в нуле равен −1."},{"title":"Шаг 3","text":"В правой полуокрестности она постоянна, поэтому правый предел равен 1."},{"title":"Шаг 4","text":"По критерию односторонних пределов двусторонний предел существовал бы только при их совпадении."},{"title":"Шаг 5","text":"Так как −1≠1, общего предела нет. Назначение sgn 0=0 не меняет ни одного из этих пределов."}],"source":"Нарешка · Односторонние пределы и критерий Коши"},{"id":"legacy-onesided-5","topicId":27,"question":"Что сравнивают в критерии Коши для функции?","options":["f(x₁) и f(x₂) при двух близких к x₀ аргументах","только f(x₀) и предел","x₁ и f(x₂)"],"correct":0,"steps":[{"title":"Шаг 1","text":"Критерий Коши позволяет проверять существование конечного предела без предварительного выбора числа A."},{"title":"Шаг 2","text":"Для любого ε>0 нужно найти δ>0, чтобы любые x₁,x₂ из проколотой δ-окрестности точки x₀ давали |f(x₁)−f(x₂)|<ε."},{"title":"Шаг 3","text":"Условия имеют вид 0<|x₁−x₀|<δ и 0<|x₂−x₀|<δ. Оба аргумента обязаны приближаться к x₀."},{"title":"Шаг 4","text":"Сравниваются именно два значения функции, а не только расстояние между самими аргументами."},{"title":"Шаг 5","text":"Если в любой такой окрестности сохраняется пара значений с разностью не меньше одного фиксированного ε₀, критерий нарушен и конечного предела нет."}],"source":"Нарешка · Односторонние пределы и критерий Коши"},{"id":"legacy-onesided-6","topicId":28,"question":"limₓ→0⁻ 1/x равен…","options":["+∞","−∞","1"],"correct":1,"steps":[{"title":"Шаг 1","text":"При x→0⁻ рассматриваются отрицательные аргументы, поэтому 1/x<0."},{"title":"Шаг 2","text":"Для доказательства предела −∞ нужно при каждом M>0 получить 1/x<−M для всех достаточно близких отрицательных x."},{"title":"Шаг 3","text":"Запишем x=−t с t>0. Тогда 1/x=−1/t."},{"title":"Шаг 4","text":"Если 0<t<1/M, то 1/t>M, а значит −1/t<−M."},{"title":"Шаг 5","text":"Следовательно, подходит левая окрестность −1/M<x<0. Предел равен −∞."}],"source":"Нарешка · Односторонние пределы и критерий Коши"},{"id":"legacy-onesided-7","topicId":35,"question":"Если lim слева =4, lim справа =4, то…","options":["двусторонний предел равен 4","предела нет","нужно знать f(x₀)"],"correct":0,"steps":[{"title":"Шаг 1","text":"По условию оба односторонних предела существуют и равны 4."},{"title":"Шаг 2","text":"Для ε>0 левый предел даёт радиус δ₋ с |f(x)−4|<ε слева от точки."},{"title":"Шаг 3","text":"Правый предел даёт радиус δ₊ с той же оценкой справа."},{"title":"Шаг 4","text":"При δ=min(δ₋,δ₊) любая точка проколотой двусторонней окрестности попадает в одну из этих двух сторон и удовлетворяет оценке."},{"title":"Шаг 5","text":"Значит, двусторонний предел равен 4. О значении функции в самой точке из этого ничего не следует."}],"source":"Нарешка · Односторонние пределы и критерий Коши"},{"id":"legacy-onesided-8","topicId":35,"question":"Если левый предел равен 2, а правый 3, то…","options":["предел равен 2,5","двустороннего предела нет","предел равен 3"],"correct":1,"steps":[{"title":"Шаг 1","text":"Предположим для противоречия, что двусторонний предел равен некоторому A."},{"title":"Шаг 2","text":"Тогда при ограничении аргументов только слева получился бы тот же предел A. По условию он равен 2, значит A=2."},{"title":"Шаг 3","text":"При ограничении только справа общий предел также должен был бы равняться A. Но по условию правый предел равен 3, значит A=3."},{"title":"Шаг 4","text":"Из 2≠3 следует противоречие. Поэтому двустороннего предела нет."},{"title":"Шаг 5","text":"Оба односторонних предела при этом существуют. Отсутствие общего предела не означает отсутствие каждого из них отдельно."}],"source":"Нарешка · Односторонние пределы и критерий Коши"},{"id":"legacy-remarkable-1","topicId":25,"question":"limₓ→0 sin(4x)/(2x)=…","options":["1/2","2","4"],"correct":1,"steps":[{"title":"Шаг 1","text":"При x→0 исходное отношение имеет вид 0/0, поэтому выделяем первый замечательный предел."},{"title":"Шаг 2","text":"При x≠0 переписываем sin(4x)/(2x)=2·sin(4x)/(4x)."},{"title":"Шаг 3","text":"Вводим t=4x. Тогда t→0, а sin t/t→1 при радианной мере угла."},{"title":"Шаг 4","text":"Постоянный множитель 2 остаётся снаружи: предел равен 2·1=2."},{"title":"Шаг 5","text":"Проверяем коэффициенты: аргумент синуса содержит 4, а знаменатель — 2, поэтому отношение коэффициентов 4/2=2."}],"source":"Нарешка · Замечательные пределы"},{"id":"legacy-remarkable-2","topicId":25,"question":"limₓ→0 sin(9x)/(3x)=…","options":["3","1","9"],"correct":0,"steps":[{"title":"Шаг 1","text":"Чтобы применить lim sin t/t=1, аргумент синуса должен совпасть с аргументом в знаменателе стандартной дроби."},{"title":"Шаг 2","text":"Для x≠0 имеем sin(9x)/(3x)=3·sin(9x)/(9x)."},{"title":"Шаг 3","text":"Положим t=9x→0. Тогда нормированная дробь sin t/t стремится к 1."},{"title":"Шаг 4","text":"По правилу постоянного множителя искомый предел равен 3."},{"title":"Шаг 5","text":"Потеря множителя 3 дала бы неверный ответ 1. Он появляется из равенства 9x=3·3x."}],"source":"Нарешка · Замечательные пределы"},{"id":"legacy-remarkable-3","topicId":26,"question":"limₓ→∞(1+1/x)ˣ равен…","options":["e","1","∞"],"correct":0,"steps":[{"title":"Шаг 1","text":"При x→+∞ величина 1/x стремится к 0 справа, а основание 1+1/x положительно."},{"title":"Шаг 2","text":"Положим t=1/x. Тогда x=1/t и t→0⁺."},{"title":"Шаг 3","text":"Исходное выражение точно превращается в (1+t)^(1/t)."},{"title":"Шаг 4","text":"По второму замечательному пределу это выражение стремится к e при t→0."},{"title":"Шаг 5","text":"Следовательно, предел равен e≈2,71828. Здесь x может быть вещественным, а не только натуральным номером последовательности."}],"source":"Нарешка · Замечательные пределы"},{"id":"legacy-remarkable-4","topicId":26,"question":"limₓ→∞(1+5/x)ˣ равен…","options":["e","e⁵","5e"],"correct":1,"steps":[{"title":"Шаг 1","text":"Запишем t=5/x. При x→+∞ имеем t→0⁺ и x=5/t."},{"title":"Шаг 2","text":"Основание 1+5/x=1+t положительно для достаточно больших x."},{"title":"Шаг 3","text":"Получаем (1+5/x)ˣ=(1+t)^(5/t)=[(1+t)^(1/t)]⁵."},{"title":"Шаг 4","text":"Выражение в квадратных скобках стремится к e по второму замечательному пределу."},{"title":"Шаг 5","text":"Непрерывность пятой степени даёт e⁵. Коэффициент 5 в добавке основания влияет на конечную степень e."}],"source":"Нарешка · Замечательные пределы"},{"id":"legacy-remarkable-5","topicId":26,"question":"limₓ→0 (1+2x)^(1/x)=…","options":["e","e²","1"],"correct":1,"steps":[{"title":"Шаг 1","text":"При достаточно малых |x|<1/4 основание 1+2x больше 1/2 и положительно."},{"title":"Шаг 2","text":"Вводим t=2x, тогда t→0, а 1/x=2/t."},{"title":"Шаг 3","text":"Получаем (1+2x)^(1/x)=[(1+t)^(1/t)]²."},{"title":"Шаг 4","text":"По второму замечательному пределу скобка стремится к e."},{"title":"Шаг 5","text":"Следовательно, искомый предел равен e². Условие x≠0 нужно для исходного показателя и согласуется с проколотой окрестностью."}],"source":"Нарешка · Замечательные пределы"},{"id":"legacy-remarkable-6","topicId":25,"question":"Значение limₓ→0 (1−cos x)/x² равно…","options":["1","1/2","0"],"correct":1,"steps":[{"title":"Шаг 1","text":"Пользуемся точным тождеством 1−cos x=2sin²(x/2)."},{"title":"Шаг 2","text":"При x≠0 преобразуем дробь: (1−cos x)/x²=(1/2)·[sin(x/2)/(x/2)]²."},{"title":"Шаг 3","text":"Аргумент x/2 стремится к 0. Поэтому отношение в скобках стремится к 1."},{"title":"Шаг 4","text":"По арифметике пределов получаем (1/2)·1²=1/2."},{"title":"Шаг 5","text":"Такой вывод не заменяет cos x на 1 внутри разности: он сохраняет её главный ненулевой порядок."}],"source":"Нарешка · Замечательные пределы"},{"id":"legacy-remarkable-7","topicId":25,"question":"В какой мере угла верен lim sin x/x=1?","options":["градусной","радианной","любой"],"correct":1,"steps":[{"title":"Шаг 1","text":"Первый замечательный предел выведен для аргумента, измеряемого в радианах: lim при t→0 sin t/t=1."},{"title":"Шаг 2","text":"В радианной мере длина дуги единичной окружности численно совпадает с углом, что используется в геометрической оценке."},{"title":"Шаг 3","text":"Если число x обозначает градусы, соответствующий радианный аргумент равен πx/180."},{"title":"Шаг 4","text":"Тогда sin(πx/180)/x=(π/180)·sin(πx/180)/(πx/180)→π/180."},{"title":"Шаг 5","text":"Поэтому значение 1 верно именно в радианной мере. Единицы измерения в данном пределе существенны."}],"source":"Нарешка · Замечательные пределы"},{"id":"legacy-remarkable-8","topicId":26,"question":"limₓ→0 (1+3x)^(4/x)=…","options":["e⁴","e¹²","e³"],"correct":1,"steps":[{"title":"Шаг 1","text":"Для достаточно малых |x|<1/6 основание 1+3x положительно."},{"title":"Шаг 2","text":"Положим t=3x. Тогда x=t/3, поэтому показатель 4/x=12/t."},{"title":"Шаг 3","text":"Точно переписываем выражение: (1+3x)^(4/x)=[(1+t)^(1/t)]¹²."},{"title":"Шаг 4","text":"По второму замечательному пределу скобка стремится к e."},{"title":"Шаг 5","text":"Искомый предел равен e¹². Число 12 получается как произведение 3 из основания и 4 из показателя."}],"source":"Нарешка · Замечательные пределы"},{"id":"legacy-infinite-1","topicId":29,"question":"Запись α(x)=o(β(x)) означает…","options":["α/β→0","α/β→1","α+β→0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Запись α=o(β) относится к одному фиксированному приближению аргумента, например x→0."},{"title":"Шаг 2","text":"На рассматриваемой проколотой области требуется, чтобы отношение α/β было определено, либо отдельно оговаривается эквивалентное представление с продолжением."},{"title":"Шаг 3","text":"Определение: α(x)/β(x)→0. Это означает, что α становится малой по сравнению с масштабом β."},{"title":"Шаг 4","text":"Например, x²=o(x) при x→0, потому что x²/x=x→0 для x≠0."},{"title":"Шаг 5","text":"Равенство α→0 само по себе недостаточно: для α=β=x отношение равно 1, а не 0."}],"source":"Нарешка · Бесконечно малые, большие и эквивалентности"},{"id":"legacy-infinite-2","topicId":29,"question":"При x→0 верно…","options":["sin x∼x","sin x∼x²","sin x∼1"],"correct":0,"steps":[{"title":"Шаг 1","text":"По определению эквивалентности нужно проверить, что отношение двух функций стремится к 1."},{"title":"Шаг 2","text":"Для sin x и x это отношение равно sin x/x при x≠0."},{"title":"Шаг 3","text":"Первый замечательный предел даёт sin x/x→1 в радианной мере угла."},{"title":"Шаг 4","text":"Следовательно, sin x∼x при x→0."},{"title":"Шаг 5","text":"Это не тождественное равенство sin x=x. Эквивалентность описывает относительную погрешность в пределе."}],"source":"Нарешка · Бесконечно малые, большие и эквивалентности"},{"id":"legacy-infinite-3","topicId":29,"question":"При x→0 верно 1−cos x∼…","options":["x","x²/2","x²"],"correct":1,"steps":[{"title":"Шаг 1","text":"Используем тождество 1−cos x=2sin²(x/2)."},{"title":"Шаг 2","text":"Разделим на предполагаемый эквивалент x²/2: (1−cos x)/(x²/2)=[sin(x/2)/(x/2)]²."},{"title":"Шаг 3","text":"При x→0 отношение внутри квадрата стремится к 1 по первому замечательному пределу."},{"title":"Шаг 4","text":"Поэтому всё отношение стремится к 1²=1."},{"title":"Шаг 5","text":"Это доказывает 1−cos x∼x²/2. Масштаб x вместо x² дал бы нулевое отношение и не являлся бы эквивалентом."}],"source":"Нарешка · Бесконечно малые, большие и эквивалентности"},{"id":"legacy-infinite-4","topicId":28,"question":"Если α(x)→0 и α(x)≠0, то 1/α(x)…","options":["тоже стремится к 0","стремится к бесконечности по модулю","стремится к 1"],"correct":1,"steps":[{"title":"Шаг 1","text":"Дано α(x)→0 и α(x)≠0 на рассматриваемой области. Поэтому обратная величина определена."},{"title":"Шаг 2","text":"Нужно доказать: для каждого M>0 модуль 1/α(x) становится больше M."},{"title":"Шаг 3","text":"Из α→0 выбираем окрестность, где |α(x)|<1/M."},{"title":"Шаг 4","text":"Поскольку модуль положителен, после обращения получаем 1/|α(x)|>M."},{"title":"Шаг 5","text":"Значит, |1/α(x)|→∞. Знак α может меняться, поэтому без дополнительных условий утверждать именно +∞ или именно −∞ нельзя."}],"source":"Нарешка · Бесконечно малые, большие и эквивалентности"},{"id":"legacy-infinite-5","topicId":26,"question":"limₓ→0 (eˣ−1)/x равен…","options":["0","1","e"],"correct":1,"steps":[{"title":"Шаг 1","text":"Это следствие второго замечательного предела для экспоненты, а не первый тригонометрический предел."},{"title":"Шаг 2","text":"Для объяснения связи положим t=eˣ−1. При x→0 получаем t→0, а x=ln(1+t)."},{"title":"Шаг 3","text":"Тогда (eˣ−1)/x=t/ln(1+t) при x≠0."},{"title":"Шаг 4","text":"Из известного следствия ln(1+t)/t→1 получаем обратное отношение t/ln(1+t)→1."},{"title":"Шаг 5","text":"Следовательно, предел равен 1. Замена eˣ на 1 прямо в числителе уничтожила бы нужную разность и не была бы вычислением предела."}],"source":"Нарешка · Бесконечно малые, большие и эквивалентности"},{"id":"legacy-infinite-6","topicId":28,"question":"limₓ→∞ (7x²+1)/(2x²−x)=…","options":["7/2","2/7","∞"],"correct":0,"steps":[{"title":"Шаг 1","text":"При x→+∞ выделяем старшую степень x² в числителе и знаменателе."},{"title":"Шаг 2","text":"Получаем (7x²+1)/(2x²−x)=(7+1/x²)/(2−1/x)."},{"title":"Шаг 3","text":"Добавки 1/x² и 1/x стремятся к 0."},{"title":"Шаг 4","text":"Предел знаменателя равен 2≠0, поэтому предел отношения равен 7/2."},{"title":"Шаг 5","text":"Одинаковые степени дают отношение старших коэффициентов. Здесь нет ухода к бесконечности: общий множитель x² сокращается."}],"source":"Нарешка · Бесконечно малые, большие и эквивалентности"},{"id":"legacy-infinite-7","topicId":29,"question":"При x→0 сумма x+x² эквивалентна…","options":["x","x²","2x²"],"correct":0,"steps":[{"title":"Шаг 1","text":"Для эквивалентности с x нужно проверить отношение (x+x²)/x при x≠0."},{"title":"Шаг 2","text":"Сокращаем общий множитель x: получаем 1+x."},{"title":"Шаг 3","text":"При x→0 это выражение стремится к 1."},{"title":"Шаг 4","text":"Следовательно, x+x²∼x. Добавка x² имеет меньший порядок, так как x²/x=x→0."},{"title":"Шаг 5","text":"Замена всей суммы на x² была бы неверна: отношение (x+x²)/x²=1/x+1 не стремится к 1."}],"source":"Нарешка · Бесконечно малые, большие и эквивалентности"},{"id":"legacy-infinite-8","topicId":29,"question":"Где рискованно просто заменять эквиваленты?","options":["в произведении ненулевых эквивалентных множителей","в частном при ненулевом знаменателе","в разности близких слагаемых с сокращением"],"correct":2,"steps":[{"title":"Шаг 1","text":"В вопросе рассматриваются бесконечно малые. Эквивалентность контролирует отношение, но замена отдельных слагаемых внутри разности может уничтожить главный член."},{"title":"Шаг 2","text":"Например, α=x+x² и β=x−x² — бесконечно малые при x→0, причём α/x=1+x→1 и β/x=1−x→1."},{"title":"Шаг 3","text":"Их настоящая разность α−β=2x². Поэтому (α−β)/x²=2."},{"title":"Шаг 4","text":"Если заменить оба слагаемых эквивалентом x внутри разности, получится x−x=0, и отношение ошибочно даст 0 вместо 2."},{"title":"Шаг 5","text":"Следовательно, прежде чем применять эквивалентности, нужно преобразовать разность и сохранить её главный ненулевой порядок."}],"source":"Нарешка · Бесконечно малые, большие и эквивалентности"},{"id":"legacy-continuity-1","topicId":22,"question":"Непрерывность в x₀ означает…","options":["lim f(x)=f(x₀)","f(x₀)=0","существование производной"],"correct":0,"steps":[{"title":"Шаг 1","text":"Для непрерывности в x₀ значение f(x₀) должно быть определено."},{"title":"Шаг 2","text":"Если x₀ — предельная точка области, требуется существование предела f(x) при x→x₀ по этой области."},{"title":"Шаг 3","text":"Главное равенство: этот предел должен совпадать с f(x₀)."},{"title":"Шаг 4","text":"В ε-δ-форме для любого ε>0 существует δ>0, при котором x из области и |x−x₀|<δ дают |f(x)−f(x₀)|<ε."},{"title":"Шаг 5","text":"Одного существования конечного предела мало: можно назначить в точке другое значение и получить устранимый разрыв."}],"source":"Нарешка · Непрерывность и теоремы на отрезке"},{"id":"legacy-continuity-2","topicId":31,"question":"Непрерывная на [−2,3] функция…","options":["обязательно ограничена и достигает max/min","обязательно строго возрастает","имеет ровно один ноль"],"correct":0,"steps":[{"title":"Шаг 1","text":"Область [−2,3] является замкнутым ограниченным отрезком."},{"title":"Шаг 2","text":"По условию функция непрерывна на всём этом отрезке; на концах используется непрерывность относительно области."},{"title":"Шаг 3","text":"Первая теорема Вейерштрасса гарантирует ограниченность значений."},{"title":"Шаг 4","text":"Теорема о достижении точных граней даёт точки x_min,x_max∈[−2,3], в которых достигаются inf f и sup f."},{"title":"Шаг 5","text":"Поэтому функция ограничена и имеет минимум и максимум. Теоремы не сообщают конкретных значений этих экстремумов без задания самой функции."}],"source":"Нарешка · Непрерывность и теоремы на отрезке"},{"id":"legacy-continuity-3","topicId":32,"question":"Если f непрерывна на [0,2], f(0)=−3 и f(2)=5, что гарантировано?","options":["есть c∈(0,2) с f(c)=0","есть ровно 8 корней","f(1)=1"],"correct":0,"steps":[{"title":"Шаг 1","text":"Проверяем непрерывность на всём замкнутом отрезке [0,2]: она дана в условии."},{"title":"Шаг 2","text":"На концах f(0)=−3<0 и f(2)=5>0. Их произведение равно −15<0."},{"title":"Шаг 3","text":"По теореме о переходе через нуль существует точка c∈(0,2), в которой f(c)=0."},{"title":"Шаг 4","text":"Концы исключены, потому что в них функция принимает ненулевые значения −3 и 5."},{"title":"Шаг 5","text":"Единственность корня не следует: для неё понадобилось бы дополнительное свойство, например строгая монотонность."}],"source":"Нарешка · Непрерывность и теоремы на отрезке"},{"id":"legacy-continuity-4","topicId":30,"question":"Почему нельзя применить Вейерштрасса к 1/x на (0,1]?","options":["область не является замкнутым отрезком","функция непрерывна","значение в 1 равно 1"],"correct":0,"steps":[{"title":"Шаг 1","text":"Функция 1/x непрерывна в каждой точке (0,1]. Разрыв в точке 1 отсутствует."},{"title":"Шаг 2","text":"Однако множество (0,1] не замкнуто: последовательность 1/n из него сходится к 0, который в область не входит."},{"title":"Шаг 3","text":"На этих аргументах функция имеет значения f(1/n)=n и потому неограниченна сверху."},{"title":"Шаг 4","text":"Теорема Вейерштрасса требует непрерывности на замкнутом ограниченном отрезке. Здесь условие замкнутости нарушено."},{"title":"Шаг 5","text":"Поэтому применять её нельзя; неограниченность примера не опровергает теорему с полным набором гипотез."}],"source":"Нарешка · Непрерывность и теоремы на отрезке"},{"id":"legacy-continuity-5","topicId":24,"question":"Многочлен x⁵−3x+1…","options":["непрерывен на всей ℝ","непрерывен только при x>0","не обязательно непрерывен"],"correct":0,"steps":[{"title":"Шаг 1","text":"Функции x, постоянные числа и их конечные произведения непрерывны на ℝ."},{"title":"Шаг 2","text":"Следовательно, степень x⁵ непрерывна на ℝ."},{"title":"Шаг 3","text":"Умножение x на константу −3 сохраняет непрерывность, поэтому −3x также непрерывна."},{"title":"Шаг 4","text":"Сумма непрерывных функций x⁵,−3x и 1 непрерывна в каждой вещественной точке."},{"title":"Шаг 5","text":"У многочлена нет знаменателей, корней чётной степени или логарифмов, которые ограничивали бы область. Ответ — вся ℝ."}],"source":"Нарешка · Непрерывность и теоремы на отрезке"},{"id":"legacy-continuity-6","topicId":32,"question":"Для существования корня по теореме о переходе через ноль нужно…","options":["f(a)f(b)<0 и непрерывность на [a,b]","только f(a)=0","строгая монотонность"],"correct":0,"steps":[{"title":"Шаг 1","text":"Теорема о переходе через нуль применяется к функции, непрерывной на всём [a,b]."},{"title":"Шаг 2","text":"Для гарантии корня внутри отрезка дополнительно требуются противоположные знаки f(a) и f(b), то есть f(a)f(b)<0."},{"title":"Шаг 3","text":"Тогда 0 строго находится между концевыми значениями, и непрерывность заставляет функцию принять его в некоторой c∈(a,b)."},{"title":"Шаг 4","text":"Без непрерывности ступенчатая функция может перескочить с −1 на 1, так и не приняв 0."},{"title":"Шаг 5","text":"Если знак на концах одинаков, корень всё ещё может существовать, но эта теорема не гарантирует его по одним концевым значениям."}],"source":"Нарешка · Непрерывность и теоремы на отрезке"},{"id":"legacy-continuity-7","topicId":32,"question":"Если функция непрерывна и строго возрастает, то уравнение f(x)=0…","options":["может иметь не более одного корня","обязательно имеет два корня","не имеет корней"],"correct":0,"steps":[{"title":"Шаг 1","text":"Допустим, у строго возрастающей функции есть два корня x₁<x₂."},{"title":"Шаг 2","text":"Строгое возрастание требует f(x₁)<f(x₂)."},{"title":"Шаг 3","text":"Но оба корня дают f(x₁)=f(x₂)=0. Получаем невозможное неравенство 0<0."},{"title":"Шаг 4","text":"Следовательно, корней не больше одного. Непрерывность для этой части вывода даже не требуется."},{"title":"Шаг 5","text":"Существование корня отдельно не доказано: например, eˣ непрерывна и строго возрастает, но не обращается в нуль."}],"source":"Нарешка · Непрерывность и теоремы на отрезке"},{"id":"legacy-continuity-8","topicId":33,"question":"Теорема о промежуточных значениях гарантирует…","options":["каждое значение между f(a) и f(b) достигается","максимум равен f(a)","функция линейна"],"correct":0,"steps":[{"title":"Шаг 1","text":"Пусть f непрерывна на [a,b], а число y находится между f(a) и f(b)."},{"title":"Шаг 2","text":"Если y совпадает с концевым значением, соответствующий конец уже даёт нужную точку."},{"title":"Шаг 3","text":"Если y строго между ними, функция g(x)=f(x)−y непрерывна и имеет разные знаки на концах."},{"title":"Шаг 4","text":"По теореме о нуле существует c∈(a,b) с g(c)=0, то есть f(c)=y."},{"title":"Шаг 5","text":"Итак, достигается каждое промежуточное значение. Монотонность не нужна, и единственность c не обещается."}],"source":"Нарешка · Непрерывность и теоремы на отрезке"},{"id":"legacy-breaks-1","topicId":35,"question":"Если конечный предел существует, но f(x₀) не задано, разрыв…","options":["устранимый","первого рода со скачком","второго рода"],"correct":0,"steps":[{"title":"Шаг 1","text":"Пусть конечный предел lim при x→x₀ f(x)=A существует."},{"title":"Шаг 2","text":"По условию значение f(x₀) не задано, поэтому функция в этой точке пока не может быть непрерывной."},{"title":"Шаг 3","text":"Определим новую функцию, сохранив все значения вне x₀ и назначив f(x₀)=A."},{"title":"Шаг 4","text":"Предел от изменения единственного значения не меняется и теперь совпадает со значением функции. Получается непрерывность."},{"title":"Шаг 5","text":"Такой дефект устраняется доопределением в одной точке, поэтому разрыв называется устранимым."}],"source":"Нарешка · Классификация точек разрыва"},{"id":"legacy-breaks-2","topicId":35,"question":"У f(x)=1/x при x=0…","options":["устранимый разрыв","разрыв первого рода","разрыв второго рода"],"correct":2,"steps":[{"title":"Шаг 1","text":"Для f(x)=1/x справа от нуля значения положительны и неограниченно растут: предел справа +∞."},{"title":"Шаг 2","text":"Слева значения отрицательны и неограниченно убывают: предел слева −∞."},{"title":"Шаг 3","text":"Разрыв первого рода требовал бы двух конечных односторонних пределов."},{"title":"Шаг 4","text":"Здесь это требование не выполнено. По классификации разрыв относится ко второму роду."},{"title":"Шаг 5","text":"Назначение любого конечного f(0) ничего не изменит в одностороннем поведении, поэтому разрыв не устраним."}],"source":"Нарешка · Классификация точек разрыва"},{"id":"legacy-breaks-3","topicId":35,"question":"Если левый предел равен −2, правый 4, то это…","options":["устранимый разрыв","скачок первого рода величины 6","второй род"],"correct":1,"steps":[{"title":"Шаг 1","text":"Даны конечные односторонние пределы L=−2 и R=4."},{"title":"Шаг 2","text":"Так как оба конечны, разрыв относится к первому роду, если пределы не совпадают."},{"title":"Шаг 3","text":"Здесь L≠R, поэтому это скачок, а не устранимый разрыв."},{"title":"Шаг 4","text":"Величина скачка по направлению слева направо равна R−L=4−(−2)=6."},{"title":"Шаг 5","text":"Значение функции в самой точке не влияет на эти пределы и не может убрать скачок."}],"source":"Нарешка · Классификация точек разрыва"},{"id":"legacy-breaks-4","topicId":35,"question":"У f(x)=sin x/x при x≠0 разрыв в 0…","options":["устранимый","второго рода","скачок"],"correct":0,"steps":[{"title":"Шаг 1","text":"При x≠0 функция sin x/x определена в окрестности нуля."},{"title":"Шаг 2","text":"По первому замечательному пределу её двусторонний предел при x→0 равен 1."},{"title":"Шаг 3","text":"Исходная дробь в нуле не определена, так что условие равенства предела значению пока не выполнено."},{"title":"Шаг 4","text":"Если назначить f(0)=1, получим непрерывную функцию."},{"title":"Шаг 5","text":"Поэтому разрыв устранимый. Здесь нет ни скачка, ни бесконечного одностороннего поведения."}],"source":"Нарешка · Классификация точек разрыва"},{"id":"legacy-breaks-5","topicId":39,"question":"У sin(1/x) при x→0…","options":["есть предел 0","конечные односторонние пределы равны","предел не существует из-за осцилляций"],"correct":2,"steps":[{"title":"Шаг 1","text":"Рассмотрим положительные аргументы xₙ=1/(π/2+2πn) и yₙ=1/(3π/2+2πn)."},{"title":"Шаг 2","text":"Обе последовательности стремятся к 0 справа, но sin(1/xₙ)=1 и sin(1/yₙ)=−1."},{"title":"Шаг 3","text":"Следовательно, даже правого предела нет по Гейне. Отрицательные аргументы дают аналогичное колебание слева."},{"title":"Шаг 4","text":"Размах колебаний не уменьшается: значения 1 и −1 встречаются сколь угодно близко к нулю."},{"title":"Шаг 5","text":"Поэтому общего предела нет из-за осцилляций. Функция при этом ограничена; бесконечный рост не является причиной отсутствия предела."}],"source":"Нарешка · Классификация точек разрыва"},{"id":"legacy-breaks-6","topicId":35,"question":"Если f(0)=7, а оба односторонних предела равны 2, то…","options":["функция непрерывна","разрыв устранимый","скачок 5"],"correct":1,"steps":[{"title":"Шаг 1","text":"Левый и правый пределы конечны и совпадают: оба равны 2."},{"title":"Шаг 2","text":"По критерию односторонних пределов существует двусторонний предел, равный 2."},{"title":"Шаг 3","text":"Заданное значение f(0)=7 с этим пределом не совпадает, поэтому непрерывности нет."},{"title":"Шаг 4","text":"Заменяем только f(0) на 2. Остальные значения и предел сохраняются, а равенство предела значению становится верным."},{"title":"Шаг 5","text":"Значит, разрыв устранимый. Величина 7−2 не является скачком: скачок сравнивает правый и левый пределы, а не значение в точке."}],"source":"Нарешка · Классификация точек разрыва"},{"id":"legacy-breaks-7","topicId":35,"question":"Для классификации разрыва в первую очередь нужно найти…","options":["односторонние пределы","производную","интеграл"],"correct":0,"steps":[{"title":"Шаг 1","text":"Классификация разрыва основывается прежде всего на поведении функции с каждой стороны точки."},{"title":"Шаг 2","text":"Сначала вычисляют предел слева L и предел справа R либо доказывают, что какой-то из них не существует."},{"title":"Шаг 3","text":"Если оба конечны и L≠R, получают скачок первого рода."},{"title":"Шаг 4","text":"Если оба конечны и L=R, сравнивают общее значение с f(x₀): несовпадение или отсутствие значения даёт устранимый разрыв."},{"title":"Шаг 5","text":"Если хотя бы один односторонний предел бесконечен или отсутствует, это второй род. Одного значения f(x₀) для классификации недостаточно."}],"source":"Нарешка · Классификация точек разрыва"},{"id":"legacy-breaks-8","topicId":35,"question":"Если хотя бы один односторонний предел бесконечен, разрыв…","options":["устранимый","первого рода","второго рода"],"correct":2,"steps":[{"title":"Шаг 1","text":"Разрыв первого рода по определению требует существования обоих конечных односторонних пределов."},{"title":"Шаг 2","text":"Если хотя бы один из них равен +∞ или −∞, условие конечности уже нарушено."},{"title":"Шаг 3","text":"Следовательно, такая точка относится к разрывам второго рода."},{"title":"Шаг 4","text":"Например, 1/x² имеет предел +∞ с обеих сторон нуля, однако это не делает разрыв устранимым или скачком первого рода."},{"title":"Шаг 5","text":"Изменение единственного значения в точке не меняет бесконечных пределов и не восстанавливает непрерывность с конечным значением."}],"source":"Нарешка · Классификация точек разрыва"},{"id":"legacy-uniform-1","topicId":36,"question":"В чём ключевое отличие равномерной непрерывности?","options":["δ зависит от точки","одно δ подходит сразу для всех x,y области","функция постоянна"],"correct":1,"steps":[{"title":"Шаг 1","text":"Для обычной непрерывности сначала фиксируют точку a, затем по ε подбирают δ, которое может зависеть и от a."},{"title":"Шаг 2","text":"Для равномерной непрерывности сначала задают ε, затем выбирают одно δ для всей области."},{"title":"Шаг 3","text":"Это δ должно работать для каждой пары x,y из области: |x−y|<δ влечёт |f(x)−f(y)|<ε."},{"title":"Шаг 4","text":"Порядок кванторов: ∀ε>0 ∃δ>0 ∀x,y∈E. Нельзя подбирать новое δ после выбора каждой пары."},{"title":"Шаг 5","text":"Поэтому ключевое отличие — один общий радиус для всех точек, а не просто малость изменения функции около каждой фиксированной точки."}],"source":"Нарешка · Равномерная непрерывность и повторение"},{"id":"legacy-uniform-2","topicId":36,"question":"Для f(x)=3x+1 подходит…","options":["δ=ε/3","δ=3ε","δ=xε"],"correct":0,"steps":[{"title":"Шаг 1","text":"Для f(x)=3x+1 сравним значения в двух произвольных точках x,y."},{"title":"Шаг 2","text":"Разность равна f(x)−f(y)=3x+1−3y−1=3(x−y)."},{"title":"Шаг 3","text":"По модулю |f(x)−f(y)|=3|x−y|."},{"title":"Шаг 4","text":"Для ε>0 выбираем δ=ε/3. Если |x−y|<δ, то разность значений меньше 3δ=ε."},{"title":"Шаг 5","text":"Радиус не зависит ни от x, ни от y. Поэтому это доказательство равномерной непрерывности, в частности на всей ℝ."}],"source":"Нарешка · Равномерная непрерывность и повторение"},{"id":"legacy-uniform-3","topicId":37,"question":"Непрерывная функция на [a,b]…","options":["равномерно непрерывна","обязательно линейна","обязательно ограничена только сверху"],"correct":0,"steps":[{"title":"Шаг 1","text":"Предполагается непрерывность на замкнутом ограниченном отрезке [a,b]."},{"title":"Шаг 2","text":"Теорема Кантора утверждает, что при этих условиях функция равномерно непрерывна."},{"title":"Шаг 3","text":"Иначе существовали бы ε₀>0 и пары xₙ,yₙ∈[a,b] с |xₙ−yₙ|<1/n, но |f(xₙ)−f(yₙ)|≥ε₀."},{"title":"Шаг 4","text":"Из xₙ выделяется подпоследовательность к c∈[a,b]; тогда соответствующие yₙ тоже стремятся к c. Непрерывность даёт разность значений →0."},{"title":"Шаг 5","text":"Это противоречит оценке снизу ε₀. Поэтому один δ для всей области действительно существует."}],"source":"Нарешка · Равномерная непрерывность и повторение"},{"id":"legacy-uniform-4","topicId":21,"question":"Вычисли limₓ→0 (√(1+x)−1)/x.","options":["1/2","1","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"При x=0 дробь даёт 0/0. Умножаем числитель и знаменатель на сопряжённое √(1+x)+1."},{"title":"Шаг 2","text":"Разность квадратов в числителе равна (1+x)−1=x."},{"title":"Шаг 3","text":"Для малых x≠0 получаем (√(1+x)−1)/x=1/(√(1+x)+1)."},{"title":"Шаг 4","text":"Корень непрерывен в 1, поэтому знаменатель стремится к 1+1=2≠0."},{"title":"Шаг 5","text":"Предел равен 1/2. Сокращение x допустимо на проколотой окрестности нуля, а основание корня там положительно."}],"source":"Нарешка · Равномерная непрерывность и повторение"},{"id":"legacy-uniform-5","topicId":36,"question":"Что означает «δ зависит от x₀»?","options":["обычная непрерывность может требовать разные радиусы в разных точках","функция обязательно разрывна","предел бесконечен"],"correct":0,"steps":[{"title":"Шаг 1","text":"В определении обычной непрерывности точка x₀ фиксируется до выбора δ."},{"title":"Шаг 2","text":"Поэтому в одной точке может подходить большой радиус, а в другой при той же ε потребуется меньший."},{"title":"Шаг 3","text":"Например, для 1/x при x₀=a>0 оценка |1/x−1/a|≤2|x−a|/a² получается при |x−a|<a/2."},{"title":"Шаг 4","text":"Подходящий радиус δ=min(a/2,εa²/2) явно зависит от a."},{"title":"Шаг 5","text":"Равномерная непрерывность требовала бы заменить семейство таких радиусов одним положительным числом, работающим сразу для всех точек области."}],"source":"Нарешка · Равномерная непрерывность и повторение"},{"id":"legacy-uniform-6","topicId":37,"question":"Какой набор условий теоремы Кантора верен?","options":["непрерывность на замкнутом ограниченном отрезке","монотонность на открытом интервале","ограниченность последовательности"],"correct":0,"steps":[{"title":"Шаг 1","text":"Теорема Кантора относится к функции, непрерывной на всём замкнутом ограниченном отрезке [a,b]."},{"title":"Шаг 2","text":"Замкнутость нужна, чтобы предельные точки выбранных последовательностей оставались в области функции."},{"title":"Шаг 3","text":"Ограниченность области позволяет применять теорему Больцано–Вейерштрасса к последовательности аргументов."},{"title":"Шаг 4","text":"Непрерывность переносит близость аргументов к общему предельному значению функции."},{"title":"Шаг 5","text":"Поэтому правильный набор — все три условия вместе. Например, 1/x непрерывна на (0,1], но этот незамкнутый интервал не обеспечивает равномерной непрерывности."}],"source":"Нарешка · Равномерная непрерывность и повторение"},{"id":"legacy-uniform-7","topicId":21,"question":"Какой метод удобен для дроби с корнем и разностью вида √A−√B?","options":["умножить на сопряжённое","сразу применить правило частного с 0 в знаменателе","заменить корень квадратом"],"correct":0,"steps":[{"title":"Шаг 1","text":"Сопряжённым к √A−√B называется √A+√B."},{"title":"Шаг 2","text":"Их произведение равно A−B по формуле разности квадратов."},{"title":"Шаг 3","text":"Поэтому при допустимых корнях и ненулевой сумме можно переписать √A−√B=(A−B)/(√A+√B)."},{"title":"Шаг 4","text":"Если в A−B появляется общий множитель знаменателя исходной дроби, его можно сократить вне предельной точки."},{"title":"Шаг 5","text":"Например, (√(1+x)−1)/x превращается в 1/(√(1+x)+1). Важно сначала выполнить точное преобразование, а затем переходить к пределу."}],"source":"Нарешка · Равномерная непрерывность и повторение"},{"id":"legacy-uniform-8","topicId":36,"question":"Что доказывает равномерная непрерывность?","options":["непрерывность в каждой точке области","существование производной","монотонность"],"correct":0,"steps":[{"title":"Шаг 1","text":"Предположим равномерную непрерывность на области E. Для каждого ε>0 существует δ>0, работающее для всех пар из E."},{"title":"Шаг 2","text":"Зафиксируем произвольную точку a∈E."},{"title":"Шаг 3","text":"Применим общую оценку к паре x,a. Из x∈E и |x−a|<δ следует |f(x)−f(a)|<ε."},{"title":"Шаг 4","text":"Это определение обычной непрерывности в точке a относительно E. Так как a произвольна, функция непрерывна во всех точках области."},{"title":"Шаг 5","text":"Обратное неверно без дополнительных условий: 1/x непрерывна на (0,1), но пары 1/n и 1/(n+1) становятся близкими, сохраняя разность значений 1."}],"source":"Нарешка · Равномерная непрерывность и повторение"},{"id":"legacy-logic-1","topicId":1,"question":"Отрицание «для всех x∈X верно P(x)» — это…","options":["для всех x неверно P(x)","существует x∈X, для которого P(x) неверно","не существует x∈X"],"correct":1,"steps":[{"title":"Шаг 1","text":"Высказывание ∀x∈X P(x) означает, что свойство выполняется для каждого элемента X."},{"title":"Шаг 2","text":"Чтобы оно было ложным, не требуется провала на всех элементах: достаточно хотя бы одного нарушителя."},{"title":"Шаг 3","text":"Поэтому внешний квантор ∀ заменяется на ∃, а утверждение P заменяется на ¬P."},{"title":"Шаг 4","text":"Получаем ∃x∈X:¬P(x). Область X при отрицании сохраняется."},{"title":"Шаг 5","text":"Например, отрицание «все числа X положительны» — «в X есть неположительное число», а не «все числа отрицательны»."}],"source":"Нарешка · Логика и язык доказательств"},{"id":"legacy-logic-2","topicId":1,"question":"Отрицание «существует x∈X с P(x)» — это…","options":["для всех x∈X неверно P(x)","существует x∈X с ¬P(x)","для всех x верно P(x)"],"correct":0,"steps":[{"title":"Шаг 1","text":"Высказывание ∃x∈X P(x) утверждает наличие хотя бы одного подходящего элемента."},{"title":"Шаг 2","text":"Его отрицание должно исключить каждого возможного кандидата."},{"title":"Шаг 3","text":"Поэтому для всех x∈X должно быть неверно P(x): ∀x∈X ¬P(x)."},{"title":"Шаг 4","text":"Квантор ∃ меняется на ∀, а область X остаётся той же."},{"title":"Шаг 5","text":"Например, отрицание «существует нулевой элемент» — «каждый элемент ненулевой». Нельзя опровергнуть существование одним неподходящим примером."}],"source":"Нарешка · Логика и язык доказательств"},{"id":"legacy-logic-3","topicId":1,"question":"Как записать отрицание P⇒Q?","options":["¬P⇒¬Q","P∧¬Q","¬P∨Q"],"correct":1,"steps":[{"title":"Шаг 1","text":"Импликация P⇒Q означает: если условие P выполнено, заключение Q тоже должно выполняться."},{"title":"Шаг 2","text":"Она ложна ровно в ситуации, когда P истинно, а Q ложно."},{"title":"Шаг 3","text":"Соединение этих двух требований записывается P∧¬Q."},{"title":"Шаг 4","text":"Следовательно, ¬(P⇒Q) равносильно P∧¬Q."},{"title":"Шаг 5","text":"Например, обещание «если сдал тест, получишь зачёт» опровергается случаем «сдал тест, но зачёт не получил», а не любым случаем несданного теста."}],"source":"Нарешка · Логика и язык доказательств"},{"id":"legacy-logic-4","topicId":1,"question":"Чтобы опровергнуть «∀x∈ℝ: x²<0», нужно…","options":["найти хотя бы один контрпример","проверить только x>0","доказать для x>0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Утверждение имеет внешний квантор ∀: для каждого вещественного x требуется x²<0."},{"title":"Шаг 2","text":"Для его опровержения достаточно одного x, для которого x²≥0."},{"title":"Шаг 3","text":"Берём x=0. Тогда x²=0, а строгое неравенство 0<0 ложно."},{"title":"Шаг 4","text":"Значит, найден контрпример, и универсальное утверждение опровергнуто."},{"title":"Шаг 5","text":"Можно было выбрать и x=1, но проверять бесконечно много значений не требуется. Один нарушитель достаточен для отрицания ∀."}],"source":"Нарешка · Логика и язык доказательств"},{"id":"legacy-logic-5","topicId":1,"question":"Фраза «для любого ε>0 найдётся δ>0» записывается…","options":["∃ε>0 ∀δ>0","∀ε>0 ∃δ>0","∀δ>0 ∀ε>0"],"correct":1,"steps":[{"title":"Шаг 1","text":"Слова «для любого ε>0» означают универсальный квантор ∀ε>0."},{"title":"Шаг 2","text":"Слова «найдётся δ>0» означают следующий за ним квантор существования ∃δ>0."},{"title":"Шаг 3","text":"Порядок сохраняем: ∀ε>0 ∃δ>0. Выбранное δ может зависеть от уже заданного ε."},{"title":"Шаг 4","text":"Перестановка ∃δ>0 ∀ε>0 означала бы существование одного общего δ для всех точностей и меняла бы смысл."},{"title":"Шаг 5","text":"Например, в оценке 3|x−a|<ε естественно выбирать δ=ε/3, поэтому зависимость от ε принципиальна."}],"source":"Нарешка · Логика и язык доказательств"},{"id":"legacy-logic-6","topicId":1,"question":"Контрапозиция P⇒Q — это…","options":["Q⇒P","¬Q⇒¬P","¬P⇒¬Q"],"correct":1,"steps":[{"title":"Шаг 1","text":"Исходная импликация P⇒Q запрещает ситуацию P∧¬Q."},{"title":"Шаг 2","text":"Контрапозиция начинает с отрицания заключения ¬Q и утверждает отрицание условия ¬P."},{"title":"Шаг 3","text":"Получаем ¬Q⇒¬P. Она запрещает ту же ситуацию: ¬Q истинно, а ¬P ложно означает P∧¬Q."},{"title":"Шаг 4","text":"Поэтому исходная импликация и контрапозиция логически равносильны."},{"title":"Шаг 5","text":"Не путайте с обратной Q⇒P: она в общем случае не равносильна исходной, например из «делится на 4 ⇒ чётное» не следует «чётное ⇒ делится на 4»."}],"source":"Нарешка · Логика и язык доказательств"},{"id":"legacy-logic-7","topicId":1,"question":"Отрицание «существует N, после которого все члены близки» начинается…","options":["∀N ∃n>N…","∃N ∀n>N…","∃n ∀N…"],"correct":0,"steps":[{"title":"Шаг 1","text":"Пусть фиксирована требуемая точность, а исходная фраза имеет вид ∃N ∀n>N P(n)."},{"title":"Шаг 2","text":"Отрицание внешнего существования требует рассмотреть каждый предложенный номер N: получаем ∀N."},{"title":"Шаг 3","text":"Для каждого такого N нужно найти нарушающий член после него, поэтому ∀n>N меняется на ∃n>N."},{"title":"Шаг 4","text":"Само свойство P(n) меняется на ¬P(n). Полная запись: ∀N ∃n>N:¬P(n)."},{"title":"Шаг 5","text":"Если P(n) означает |xₙ−a|<ε, нарушением будет |xₙ−a|≥ε. Знак отрицания строгого < включает равенство."}],"source":"Нарешка · Логика и язык доказательств"},{"id":"legacy-logic-8","topicId":1,"question":"P⇔Q означает…","options":["только P⇒Q","P⇒Q и Q⇒P","¬P⇒Q"],"correct":1,"steps":[{"title":"Шаг 1","text":"Символ P⇔Q утверждает равносильность, то есть необходимость и достаточность каждого условия для другого."},{"title":"Шаг 2","text":"Первое направление P⇒Q доказывает, что из P следует Q."},{"title":"Шаг 3","text":"Второе направление Q⇒P доказывает, что из Q следует P."},{"title":"Шаг 4","text":"Оба направления вместе записываются (P⇒Q)∧(Q⇒P)."},{"title":"Шаг 5","text":"Доказательства лишь одного направления недостаточно: из «делится на 4 ⇒ чётное» не получается равносильности, потому что число 2 нарушает обратное направление."}],"source":"Нарешка · Логика и язык доказательств"},{"id":"legacy-compactness-1","topicId":6,"question":"Если xₙ→a, любая подпоследовательность…","options":["также стремится к a","может иметь любой предел","обязательно постоянна"],"correct":0,"steps":[{"title":"Шаг 1","text":"Пусть xₙ→a и выбрана подпоследовательность с возрастающими натуральными индексами nₖ."},{"title":"Шаг 2","text":"Для ε>0 из исходной сходимости существует N, после которого |xₙ−a|<ε."},{"title":"Шаг 3","text":"Из строгого возрастания индексов следует nₖ≥k, в частности nₖ→∞."},{"title":"Шаг 4","text":"При k>N имеем nₖ>N, поэтому |xₙₖ−a|<ε."},{"title":"Шаг 5","text":"Это определение сходимости подпоследовательности к тому же a. Выделение членов не может создать другой предел у уже сходящейся последовательности."}],"source":"Нарешка · Подпоследовательности и критерии"},{"id":"legacy-compactness-2","topicId":6,"question":"xₙ=(−1)ⁿ имеет подпоследовательности с пределами…","options":["0 и 1","−1 и 1","только 0"],"correct":1,"steps":[{"title":"Шаг 1","text":"Выбираем чётные индексы nₖ=2k. Тогда xₙₖ=(−1)²ᵏ=1 для всех k."},{"title":"Шаг 2","text":"Полученная постоянная подпоследовательность сходится к 1."},{"title":"Шаг 3","text":"Выбираем нечётные индексы mₖ=2k−1. Тогда xₘₖ=−1 для всех k и предел равен −1."},{"title":"Шаг 4","text":"Следовательно, у исходной последовательности есть подпоследовательности с двумя разными пределами −1 и 1."},{"title":"Шаг 5","text":"Это не два предела всей последовательности: наличие разных подпоследовательных пределов как раз исключает её общую сходимость."}],"source":"Нарешка · Подпоследовательности и критерии"},{"id":"legacy-compactness-3","topicId":17,"question":"Что гарантирует Больцано—Вейерштрасс?","options":["вся ограниченная последовательность сходится","у любой ограниченной последовательности есть сходящаяся подпоследовательность","монотонность"],"correct":1,"steps":[{"title":"Шаг 1","text":"Теорема Больцано–Вейерштрасса начинается с ограниченной вещественной последовательности."},{"title":"Шаг 2","text":"Все её члены можно поместить в некоторый замкнутый отрезок."},{"title":"Шаг 3","text":"Последовательно делят отрезок пополам и каждый раз оставляют половину с бесконечно многими членами. Получаются вложенные отрезки с длинами, стремящимися к нулю."},{"title":"Шаг 4","text":"В каждом отрезке выбирают очередной член с индексом больше предыдущего. Эти выбранные члены сходятся к общей точке отрезков."},{"title":"Шаг 5","text":"Таким образом, гарантирована сходящаяся подпоследовательность. Сходимость всей последовательности из одной ограниченности не следует."}],"source":"Нарешка · Подпоследовательности и критерии"},{"id":"legacy-compactness-4","topicId":16,"question":"Вложенные отрезки имеют длины →0. Их пересечение…","options":["пустое","содержит ровно одну точку","содержит отрезок"],"correct":1,"steps":[{"title":"Шаг 1","text":"Пусть непустые замкнутые отрезки Iₙ=[aₙ,bₙ] вложены, а bₙ−aₙ→0."},{"title":"Шаг 2","text":"Левые концы aₙ не убывают и ограничены сверху b₁. Пусть c=sup{aₙ}."},{"title":"Шаг 3","text":"Для каждого n имеем aₙ≤c≤bₙ: все левые концы более поздних отрезков тоже не превышают bₙ. Поэтому c входит во все Iₙ."},{"title":"Шаг 4","text":"Если бы d тоже входило во все отрезки, то |c−d|≤bₙ−aₙ для каждого n."},{"title":"Шаг 5","text":"Переход к пределу даёт |c−d|=0, то есть c=d. Общая часть содержит ровно одну точку."}],"source":"Нарешка · Подпоследовательности и критерии"},{"id":"legacy-compactness-5","topicId":18,"question":"Критерий Коши требует, чтобы…","options":["член был близок к известному a","любые два достаточно поздних члена были близки","последовательность была монотонной"],"correct":1,"steps":[{"title":"Шаг 1","text":"Критерий требует для каждого ε>0 найти N, после которого близка любая пара членов."},{"title":"Шаг 2","text":"Это записывается как ∀m,n>N: |xₘ−xₙ|<ε."},{"title":"Шаг 3","text":"Оба номера выбираются независимо, а не только как n и n+1."},{"title":"Шаг 4","text":"Например, у гармонических сумм соседняя разность 1/(n+1) стремится к нулю, но H₂ₙ−Hₙ≥1/2. Поэтому соседняя близость не заменяет критерий."},{"title":"Шаг 5","text":"В ℝ выполнение полного условия Коши равносильно существованию конечного предела."}],"source":"Нарешка · Подпоследовательности и критерии"},{"id":"legacy-compactness-6","topicId":6,"question":"Если две подпоследовательности имеют разные пределы, исходная…","options":["не имеет предела","сходится к их среднему","сходится к большему"],"correct":0,"steps":[{"title":"Шаг 1","text":"Пусть xₙₖ→a и xₘₖ→b при a≠b."},{"title":"Шаг 2","text":"Допустим противное: вся последовательность xₙ сходится к c."},{"title":"Шаг 3","text":"Любая подпоследовательность сходящейся последовательности должна иметь тот же предел c, поэтому a=c и b=c."},{"title":"Шаг 4","text":"Из этих равенств следовало бы a=b, вопреки условию."},{"title":"Шаг 5","text":"Значит, исходная последовательность не имеет конечного предела. Отдельные сходящиеся подпоследовательности при этом существуют."}],"source":"Нарешка · Подпоследовательности и критерии"},{"id":"legacy-compactness-7","topicId":18,"question":"Последовательность Коши в ℝ…","options":["обязательно сходится","может быть неограниченной","не имеет подпоследовательностей"],"correct":0,"steps":[{"title":"Шаг 1","text":"По условию последовательность удовлетворяет полному критерию Коши: все достаточно поздние пары сколь угодно близки."},{"title":"Шаг 2","text":"При ε=1 хвост находится на расстоянии меньше 1 от одного фиксированного члена. Вместе с конечным началом это доказывает ограниченность."},{"title":"Шаг 3","text":"По Больцано–Вейерштрассу существует подпоследовательность xₙₖ→a∈ℝ."},{"title":"Шаг 4","text":"Для заданной ε>0 выбираем Коши-номер для ε/2 и затем член подпоследовательности после этого номера с |xₙₖ−a|<ε/2."},{"title":"Шаг 5","text":"Для любого позднего n имеем |xₙ−a|≤|xₙ−xₙₖ|+|xₙₖ−a|<ε. Значит, вся последовательность сходится к a. Использована полнота ℝ."}],"source":"Нарешка · Подпоследовательности и критерии"},{"id":"legacy-compactness-8","topicId":16,"question":"Если вложенные отрезки не сжимаются, пересечение…","options":["обязательно одна точка","может содержать много точек","обязательно пусто"],"correct":1,"steps":[{"title":"Шаг 1","text":"Условие сжатия длин до нуля отвечает за единственность общей точки, а не просто за вложенность."},{"title":"Шаг 2","text":"Возьмём Iₙ=[0,1] для каждого n. Отрезки непусты, замкнуты и вложены друг в друга."},{"title":"Шаг 3","text":"Их длины постоянно равны 1 и не стремятся к нулю."},{"title":"Шаг 4","text":"Пересечение всех Iₙ равно [0,1], то есть содержит бесконечно много точек."},{"title":"Шаг 5","text":"Следовательно, без сжатия общая часть может быть целым отрезком. При стандартных условиях вложенности непустых замкнутых ограниченных отрезков она всё же непуста."}],"source":"Нарешка · Подпоследовательности и критерии"},{"id":"legacy-combinatorics-1","topicId":15,"question":"Вычисли C₆².","options":["12","15","30"],"correct":1,"steps":[{"title":"Шаг 1","text":"Сочетание C₆² считает неупорядоченные пары из шести различных элементов."},{"title":"Шаг 2","text":"По формуле C₆²=6!/(2!·4!)."},{"title":"Шаг 3","text":"Сокращаем 4!: остаётся (6·5)/(2·1)."},{"title":"Шаг 4","text":"Получаем 30/2=15. Деление на 2! убирает два порядка записи одной и той же пары."},{"title":"Шаг 5","text":"Проверка: упорядоченных пар без повторения 6·5=30; каждая неупорядоченная пара посчитана дважды, значит их 15."}],"source":"Нарешка · Сочетания, бином Ньютона и e"},{"id":"legacy-combinatorics-2","topicId":15,"question":"Чему равно 0!?","options":["0","1","не определено"],"correct":1,"steps":[{"title":"Шаг 1","text":"Факториал натурального числа задаётся произведением n·(n−1)·…·1, а для нуля нужно отдельное согласованное значение."},{"title":"Шаг 2","text":"Рекуррентное равенство n!=n·(n−1)! при n=1 даёт 1!=1·0!."},{"title":"Шаг 3","text":"Так как 1!=1, из этого следует 0!=1."},{"title":"Шаг 4","text":"Комбинаторный смысл тот же: пустой набор можно упорядочить ровно одним способом — ничего не выбирать и не переставлять."},{"title":"Шаг 5","text":"Значение 0 разрушило бы формулы Cₙ⁰=n!/(0!n!)=1 и Cₙⁿ=1. Поэтому ответ именно 1."}],"source":"Нарешка · Сочетания, бином Ньютона и e"},{"id":"legacy-combinatorics-3","topicId":15,"question":"Коэффициенты в (a+b)⁴…","options":["1,3,3,1","1,4,6,4,1","1,2,4,2,1"],"correct":1,"steps":[{"title":"Шаг 1","text":"По биному Ньютона (a+b)⁴=Σ от k=0 до 4 величины C₄ᵏa⁴⁻ᵏbᵏ."},{"title":"Шаг 2","text":"Крайние коэффициенты C₄⁰ и C₄⁴ равны 1."},{"title":"Шаг 3","text":"Следующие C₄¹=C₄³=4 по выбору одного элемента или симметрии."},{"title":"Шаг 4","text":"Средний C₄²=4!/(2!2!)=6."},{"title":"Шаг 5","text":"Получаем коэффициенты 1,4,6,4,1 и разложение a⁴+4a³b+6a²b²+4ab³+b⁴. Их сумма 16 совпадает с (1+1)⁴."}],"source":"Нарешка · Сочетания, бином Ньютона и e"},{"id":"legacy-combinatorics-4","topicId":15,"question":"Коэффициент при x² в (x+1)⁵ равен…","options":["5","10","20"],"correct":1,"steps":[{"title":"Шаг 1","text":"Чтобы получить x² из пяти множителей (x+1), нужно ровно в двух множителях выбрать x."},{"title":"Шаг 2","text":"В остальных трёх множителях выбираем 1, поэтому каждый такой выбор даёт произведение x²."},{"title":"Шаг 3","text":"Число неупорядоченных выборов равно C₅²=5!/(2!3!)."},{"title":"Шаг 4","text":"После сокращения получаем (5·4)/(2·1)=10."},{"title":"Шаг 5","text":"Следовательно, коэффициент при x² равен 10. Число 20 считало бы те же два выбранных множителя в обоих порядках."}],"source":"Нарешка · Сочетания, бином Ньютона и e"},{"id":"legacy-combinatorics-5","topicId":15,"question":"Cₙᵏ равно…","options":["Cₙⁿ⁻ᵏ","Cₖⁿ","n−k"],"correct":0,"steps":[{"title":"Шаг 1","text":"Выбор k элементов из набора из n однозначно определяет набор невыбранных элементов."},{"title":"Шаг 2","text":"В дополнении находится n−k элементов."},{"title":"Шаг 3","text":"Обратно, зная дополнение размера n−k, можно однозначно восстановить выбранные k элементов."},{"title":"Шаг 4","text":"Это взаимно однозначное соответствие доказывает Cₙᵏ=Cₙⁿ⁻ᵏ."},{"title":"Шаг 5","text":"Та же симметрия видна из формулы n!/[k!(n−k)!]: перестановка двух множителей знаменателя значение не меняет."}],"source":"Нарешка · Сочетания, бином Ньютона и e"},{"id":"legacy-combinatorics-6","topicId":26,"question":"limₙ→∞(1+3/n)ⁿ равен…","options":["e","e³","3e"],"correct":1,"steps":[{"title":"Шаг 1","text":"Представим выражение как общий второй замечательный предел с добавкой 3/n."},{"title":"Шаг 2","text":"Положим tₙ=3/n. Тогда tₙ→0⁺ и n=3/tₙ."},{"title":"Шаг 3","text":"Точно получаем (1+3/n)ⁿ=[(1+tₙ)^(1/tₙ)]³."},{"title":"Шаг 4","text":"По второму замечательному пределу выражение в скобках стремится к e."},{"title":"Шаг 5","text":"Следовательно, предел равен e³. Коэффициент 3 не исчезает, а превращается в показатель степени e."}],"source":"Нарешка · Сочетания, бином Ньютона и e"},{"id":"legacy-combinatorics-7","topicId":15,"question":"Разложение (x+2)³ равно…","options":["x³+6x²+12x+8","x³+8","x³+2x²+2x+8"],"correct":0,"steps":[{"title":"Шаг 1","text":"Используем (a+b)³=a³+3a²b+3ab²+b³."},{"title":"Шаг 2","text":"Подставляем a=x,b=2: получаем x³+3x²·2+3x·2²+2³."},{"title":"Шаг 3","text":"Вычисляем второй член: 3·2x²=6x²."},{"title":"Шаг 4","text":"Третий член равен 3·4x=12x, последний равен 8."},{"title":"Шаг 5","text":"Итак, (x+2)³=x³+6x²+12x+8. Проверка при x=0 даёт 8 с обеих сторон."}],"source":"Нарешка · Сочетания, бином Ньютона и e"},{"id":"legacy-combinatorics-8","topicId":15,"question":"Тождество Паскаля утверждает…","options":["Cₙᵏ=Cₙ₋₁ᵏ+Cₙ₋₁ᵏ⁻¹","Cₙᵏ=n·k","Cₙᵏ=Cₖⁿ"],"correct":0,"steps":[{"title":"Шаг 1","text":"Пусть нужно выбрать k элементов из n при 1≤k≤n−1. Выделим один конкретный элемент набора."},{"title":"Шаг 2","text":"Все варианты разбиваются на два непересекающихся класса: выделенный элемент выбран или не выбран."},{"title":"Шаг 3","text":"Если он не выбран, все k элементов выбираются из остальных n−1: это Cₙ₋₁ᵏ способов."},{"title":"Шаг 4","text":"Если выбран, остаётся добрать k−1 из остальных n−1: это Cₙ₋₁ᵏ⁻¹ способов."},{"title":"Шаг 5","text":"Складывая размеры классов, получаем тождество Паскаля Cₙᵏ=Cₙ₋₁ᵏ+Cₙ₋₁ᵏ⁻¹. Краевые случаи задаются равенствами Cₙ⁰=Cₙⁿ=1."}],"source":"Нарешка · Сочетания, бином Ньютона и e"},{"id":"legacy-kr-1","topicId":21,"question":"Вариант 1 · №1. Вычисли limₓ→₂ (x³−12x+16)/(x²−4), не используя эквивалентности.","options":["0","3","−3","предел не существует"],"correct":0,"steps":[{"title":"Шаг 1","text":"При x=2 числитель и знаменатель равны нулю, поэтому сначала нужна факторизация."},{"title":"Шаг 2","text":"Числитель x³−12x+16 раскладывается как (x−2)²(x+4). Раскрытие скобок возвращает x³−12x+16."},{"title":"Шаг 3","text":"Знаменатель x²−4=(x−2)(x+2)."},{"title":"Шаг 4","text":"При x≠2 сокращаем один множитель x−2 и получаем (x−2)(x+4)/(x+2)."},{"title":"Шаг 5","text":"Оставшийся знаменатель при x=2 равен 4≠0. Числитель стремится к 0·6=0."},{"title":"Шаг 6","text":"По правилу частного предел равен 0. Эквивалентности и правило Лопиталя не использовались."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-2","topicId":28,"question":"Вариант 1 · №2. Вычисли limₓ→−∞ (√(1+2x+x²)−√(1−4x+x²)).","options":["−3","3","−2","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Обозначим A=√(x²+2x+1), B=√(x²−4x+1). Для достаточно больших отрицательных x оба корня определены."},{"title":"Шаг 2","text":"Умножаем разность на сопряжённое: A−B=(A²−B²)/(A+B)=6x/(A+B)."},{"title":"Шаг 3","text":"Выносим из каждого корня |x|, а не x: A=|x|√(1+2/x+1/x²), B=|x|√(1−4/x+1/x²)."},{"title":"Шаг 4","text":"Так как x→−∞, имеем |x|=−x. Поэтому 6x/(A+B)=−6/[√(1+2/x+1/x²)+√(1−4/x+1/x²)]."},{"title":"Шаг 5","text":"Оба корня в знаменателе стремятся к 1, их сумма — к 2."},{"title":"Шаг 6","text":"Получаем предел −6/2=−3. Ошибка в знаке обычно возникает при незаконной замене √(x²) на x на отрицательной полуоси."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-3","topicId":21,"question":"Вариант 1 · №3. Вычисли limₓ→₃ (∛(x+5)−2)/(x²−2x−3).","options":["1/48","1/24","1/12","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Положим a=∛(x+5). При x→3 имеем a→2. В исходной дроби возникает 0/0."},{"title":"Шаг 2","text":"Формула разности кубов даёт (a−2)(a²+2a+4)=a³−8=x−3."},{"title":"Шаг 3","text":"Значит, a−2=(x−3)/(a²+2a+4). Сумма в знаменателе положительна в окрестности a=2."},{"title":"Шаг 4","text":"Исходный знаменатель x²−2x−3=(x−3)(x+1)."},{"title":"Шаг 5","text":"При x≠3 сокращаем x−3 и получаем 1/[(a²+2a+4)(x+1)]."},{"title":"Шаг 6","text":"Переходя к пределу, считаем (4+4+4)·4=48 в знаменателе. Ответ равен 1/48."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-4","topicId":25,"question":"Вариант 1 · №4. Вычисли limₓ→₀ x·ctg(πx+x²).","options":["1/π","π","0","−1/π"],"correct":0,"steps":[{"title":"Шаг 1","text":"Обозначим t=πx+x²=x(π+x). При x→0 имеем t→0."},{"title":"Шаг 2","text":"Котангенс равен cos t/sin t, поэтому x·ctg t=x cos t/sin t."},{"title":"Шаг 3","text":"В проколотой достаточно малой окрестности переписываем это как [x/t]·[t/sin t]·cos t."},{"title":"Шаг 4","text":"Первый множитель равен 1/(π+x) и стремится к 1/π."},{"title":"Шаг 5","text":"Второй стремится к 1 по первому замечательному пределу; третий также стремится к 1."},{"title":"Шаг 6","text":"Перемножаем пределы: результат 1/π. Эквивалентности не нужны: использованы точное преобразование и стандартный предел."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-5","topicId":25,"question":"Вариант 1 · №5. Вычисли limₓ→π/4 (√2−2cos x)/(π−4x), не используя эквивалентности.","options":["−√2/4","√2/4","−1/2","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Пусть a=π/4 и h=x−a→0. Тогда π−4x=−4h, а √2=2cos a."},{"title":"Шаг 2","text":"Числитель равен 2(cos a−cos(a+h)). По формуле разности косинусов это 4sin(a+h/2)sin(h/2)."},{"title":"Шаг 3","text":"Делим на −4h: получаем −sin(a+h/2)·sin(h/2)/h."},{"title":"Шаг 4","text":"Нормируем малый аргумент: sin(h/2)/h=(1/2)·sin(h/2)/(h/2)→1/2."},{"title":"Шаг 5","text":"Первый синус стремится к sin a=√2/2."},{"title":"Шаг 6","text":"Предел равен −(√2/2)·(1/2)=−√2/4. Минус приходит из исходного знаменателя, его нельзя потерять."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-6","topicId":26,"question":"Вариант 1 · №6. Вычисли limₓ→∞ ((x+3)/(x−2))^(2x+1).","options":["e¹⁰","e⁵","e⁻¹⁰","1"],"correct":0,"steps":[{"title":"Шаг 1","text":"Преобразуем основание: (x+3)/(x−2)=1+5/(x−2)."},{"title":"Шаг 2","text":"Положим u=5/(x−2)→0 при x→+∞. Основание положительно для всех достаточно больших x."},{"title":"Шаг 3","text":"Показатель p=2x+1. Произведение pu=5(2x+1)/(x−2) стремится к 10."},{"title":"Шаг 4","text":"Точно запишем (1+u)ᵖ=[(1+u)^(1/u)]^(pu) при u≠0."},{"title":"Шаг 5","text":"Внутренняя скобка стремится к e по второму замечательному пределу, внешний показатель — к 10. Непрерывность положительной степени, или логарифмирование, даёт e¹⁰."},{"title":"Шаг 6","text":"Проверка логарифмом: p ln(1+u)=pu·[ln(1+u)/u]→10·1=10, поэтому само выражение стремится к exp(10)."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-7","topicId":26,"question":"Вариант 1 · №7. Вычисли limₓ→₂ (log₃x−log₃2)/(x²−4), не используя эквивалентности.","options":["1/(8 ln 3)","1/(4 ln 3)","ln 3/8","1/8"],"correct":0,"steps":[{"title":"Шаг 1","text":"Разность логарифмов равна log₃x−log₃2=ln(x/2)/ln3 при x>0."},{"title":"Шаг 2","text":"Положим h=(x−2)/2. Тогда x=2(1+h), h→0 и ln(x/2)=ln(1+h)."},{"title":"Шаг 3","text":"Знаменатель x²−4=(x−2)(x+2)=2h(x+2)."},{"title":"Шаг 4","text":"Для x≠2 получаем [ln(1+h)/h]·1/[2(x+2)ln3]."},{"title":"Шаг 5","text":"Первый множитель стремится к 1 по логарифмическому следствию второго замечательного предела."},{"title":"Шаг 6","text":"Второй стремится к 1/[2·4·ln3]. Ответ 1/(8ln3). Применялись пределы отношений, а не замена слагаемых эквивалентами в разности."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-8","topicId":29,"question":"Вариант 1 · №8. Вычисли limₓ→₀ (e^(2x²)−cos 3x)/(¹⁰√(2x²+10)−¹⁰√10), используя эквивалентности.","options":["(65/2)·10^(9/10)","65·10^(9/10)","13·10^(9/10)","13/2"],"correct":0,"steps":[{"title":"Шаг 1","text":"Здесь эквивалентности разрешены. Представим числитель как (e^(2x²)−1)+(1−cos3x), чтобы отдельно раскрыть две малые разности."},{"title":"Шаг 2","text":"Из eᵗ−1∼t получаем e^(2x²)−1∼2x²."},{"title":"Шаг 3","text":"Из 1−cos t∼t²/2 получаем 1−cos3x∼9x²/2."},{"title":"Шаг 4","text":"Оба ведущих коэффициента положительны, поэтому сумма имеет ведущий член (2+9/2)x²=(13/2)x²; сокращения ведущих частей нет."},{"title":"Шаг 5","text":"Знаменатель равен 10^(1/10)[(1+x²/5)^(1/10)−1]. По (1+t)^r−1∼rt он эквивалентен 10^(1/10)·(1/10)·x²/5."},{"title":"Шаг 6","text":"Упрощаем коэффициент: это x²/[5·10^(9/10)]."},{"title":"Шаг 7","text":"Отношение ведущих частей равно (13/2)·5·10^(9/10)=(65/2)·10^(9/10)."},{"title":"Шаг 8","text":"Это и есть предел. Не следует заменять e^(2x²) и cos3x отдельно на 1: такая замена уничтожила бы всю значимую разность."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-9","topicId":35,"question":"Вариант 2 · №1. Вычисли limₓ→−₁ (x²−1)/(x³−3x−2).","options":["двустороннего предела нет: слева −∞, справа +∞","+∞ с обеих сторон","−∞ с обеих сторон","−2/3"],"correct":0,"steps":[{"title":"Шаг 1","text":"При x=−1 обе части обращаются в нуль. Факторизуем: x²−1=(x−1)(x+1)."},{"title":"Шаг 2","text":"Кубический знаменатель равен (x−2)(x+1)²: раскрытие даёт x³−3x−2."},{"title":"Шаг 3","text":"При x≠−1 сокращаем один множитель и получаем (x−1)/[(x−2)(x+1)]."},{"title":"Шаг 4","text":"Множитель (x−1)/(x−2) стремится к (−2)/(−3)=2/3>0."},{"title":"Шаг 5","text":"Остаётся положительный по знаку множитель, умноженный на 1/(x+1). Слева от −1 величина x+1 отрицательна и стремится к 0, справа положительна."},{"title":"Шаг 6","text":"Поэтому предел слева равен −∞, справа +∞. Двустороннего предела нет даже в расширенном смысле с одним знаком бесконечности."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-10","topicId":28,"question":"Вариант 2 · №2. Вычисли limₓ→−∞ (∛(x³+x²+x+1)−∛(x³−x²+x−1)).","options":["2/3","1","−1","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Пусть a=∛(x³+x²+x+1), b=∛(x³−x²+x−1). Требуется предел a−b при x→−∞."},{"title":"Шаг 2","text":"Используем разность кубов: a−b=(a³−b³)/(a²+ab+b²)=(2x²+2)/(a²+ab+b²)."},{"title":"Шаг 3","text":"Реальный кубический корень позволяет вынести x с его знаком: a/x=∛(1+1/x+1/x²+1/x³)→1."},{"title":"Шаг 4","text":"Аналогично b/x=∛(1−1/x+1/x²−1/x³)→1."},{"title":"Шаг 5","text":"Делим числитель и знаменатель на x². Получаем (2+2/x²)/[(a/x)²+(a/x)(b/x)+(b/x)²]."},{"title":"Шаг 6","text":"Знаменатель стремится к 1+1+1=3, числитель к 2. Ответ 2/3."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-11","topicId":21,"question":"Вариант 2 · №3. Вычисли limₓ→−₁ (√(3−x)+2x)/(√(10+x)+3x), не используя эквивалентности.","options":["21/38","7/19","0","3/2"],"correct":0,"steps":[{"title":"Шаг 1","text":"При x→−1 числитель и знаменатель стремятся к 0. Введём h=x+1→0, так что x=−1+h."},{"title":"Шаг 2","text":"Числитель преобразуется в √(4−h)−2+2h. Разность корней точно равна −h/[√(4−h)+2]."},{"title":"Шаг 3","text":"Поэтому числитель равен h·[2−1/(√(4−h)+2)]."},{"title":"Шаг 4","text":"Знаменатель равен √(9+h)−3+3h=h·[3+1/(√(9+h)+3)]."},{"title":"Шаг 5","text":"При h≠0 сокращаем h. Предельное отношение равно [2−1/4]/[3+1/6]."},{"title":"Шаг 6","text":"Вычисляем: 7/4 делим на 19/6, получаем (7·6)/(4·19)=21/38. Все шаги — точные рационализации, эквивалентности не использованы."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-12","topicId":25,"question":"Вариант 2 · №4. Вычисли limₓ→₀ sin(7x+x²)/tg(3x+x³).","options":["7/3","3/7","7","1"],"correct":0,"steps":[{"title":"Шаг 1","text":"Положим u=7x+x²=x(7+x), v=3x+x³=x(3+x²). Оба стремятся к 0."},{"title":"Шаг 2","text":"Для достаточно малых x≠0 величины u,v ненулевые, а tg v определён."},{"title":"Шаг 3","text":"Переписываем sin u/tg v=[sin u/u]·[v/tg v]·[u/v]."},{"title":"Шаг 4","text":"Первые два множителя стремятся к 1 по первому замечательному пределу и его следствию для тангенса."},{"title":"Шаг 5","text":"Последний множитель равен (7+x)/(3+x²) и стремится к 7/3."},{"title":"Шаг 6","text":"Итак, общий предел равен 7/3. Сравнивать нужно целые малые аргументы u и v, а не только коэффициенты в одной из частей выражения."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-13","topicId":25,"question":"Вариант 2 · №5. Вычисли limₓ→π (cos 2x+cos 3x)/(x−π)², не используя эквивалентности.","options":["5/2","−5/2","2","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Положим h=x−π→0. Тогда знаменатель равен h², а числитель cos(2π+2h)+cos(3π+3h)=cos2h−cos3h."},{"title":"Шаг 2","text":"Формула разности косинусов даёт cos2h−cos3h=2sin(5h/2)sin(h/2)."},{"title":"Шаг 3","text":"Делим на h² и выделяем два стандартных отношения: (5/2)·[sin(5h/2)/(5h/2)]·[sin(h/2)/(h/2)]."},{"title":"Шаг 4","text":"Оба отношения стремятся к 1 при h→0."},{"title":"Шаг 5","text":"По правилу произведения предел равен 5/2."},{"title":"Шаг 6","text":"Коэффициент положителен. Перестановка косинусов в числителе изменила бы его знак, поэтому порядок исходных слагаемых важен."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-14","topicId":26,"question":"Вариант 2 · №6. Вычисли limₓ→∞ ((x²+5)/(x²−2))^(2x²+1).","options":["e¹⁴","e⁷","e⁻¹⁴","1"],"correct":0,"steps":[{"title":"Шаг 1","text":"Основание (x²+5)/(x²−2) равно 1+7/(x²−2)."},{"title":"Шаг 2","text":"Положим u=7/(x²−2)→0, p=2x²+1. Основание положительно при достаточно больших x."},{"title":"Шаг 3","text":"Вычисляем pu=7(2x²+1)/(x²−2)→14."},{"title":"Шаг 4","text":"Логарифм выражения равен p ln(1+u)=pu·[ln(1+u)/u]."},{"title":"Шаг 5","text":"По стандартному логарифмическому пределу второй множитель стремится к 1, поэтому логарифм стремится к 14."},{"title":"Шаг 6","text":"Непрерывность экспоненты даёт предел e¹⁴. Предел основания 1 сам по себе не определяет ответ при растущем показателе."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-15","topicId":26,"question":"Вариант 2 · №7. Вычисли limₓ→₃ (2ˣ−8)/(x²−9), не используя эквивалентности.","options":["(4 ln 2)/3","(8 ln 2)/3","ln 2/6","4/3"],"correct":0,"steps":[{"title":"Шаг 1","text":"Положим h=x−3→0. Тогда 2ˣ−8=8(2ʰ−1)=8(e^(h ln2)−1)."},{"title":"Шаг 2","text":"Знаменатель x²−9=(x−3)(x+3)=h(x+3)."},{"title":"Шаг 3","text":"При h≠0 переписываем дробь как [e^(h ln2)−1]/(h ln2) · [8ln2/(x+3)]."},{"title":"Шаг 4","text":"Первый множитель стремится к 1 по экспоненциальному следствию второго замечательного предела."},{"title":"Шаг 5","text":"Второй стремится к 8ln2/6=4ln2/3."},{"title":"Шаг 6","text":"Итак, предел равен (4ln2)/3. Дополнительный коэффициент 8 возникает из разложения 2³⁺ʰ=8·2ʰ."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-16","topicId":29,"question":"Вариант 2 · №8. Вычисли limₓ→₀ (⁷√(3x³+4)−⁷√4)/log₃(sin x³+e^(3x³)), используя эквивалентности.","options":["3ln3/(28·4^(6/7))","0","∞","не существует"],"correct":0,"steps":[{"title":"Шаг 1","text":"Обозначим t=x³→0. Числитель равен 4^(1/7)[(1+3t/4)^(1/7)−1]."},{"title":"Шаг 2","text":"По разрешённой эквивалентности степенной разности он эквивалентен 4^(1/7)·(1/7)·3t/4=3t/[7·4^(6/7)]."},{"title":"Шаг 3","text":"Для знаменателя запишем sin t+e^(3t)=1+w, где w=sin t+(e^(3t)−1)."},{"title":"Шаг 4","text":"Имеем sin t/t→1 и (e^(3t)−1)/t→3, поэтому w/t→4. В частности, w∼4t."},{"title":"Шаг 5","text":"Логарифм по основанию 3 равен ln(1+w)/ln3. По ln(1+w)∼w знаменатель эквивалентен 4t/ln3."},{"title":"Шаг 6","text":"В достаточно малой окрестности аргумент логарифма положителен, поскольку стремится к 1. По w/t→4 при t≠0 он также не равен 1 в достаточно малой проколотой окрестности."},{"title":"Шаг 7","text":"Делим ведущие части: [3/(7·4^(6/7))]/[4/ln3]=3ln3/[28·4^(6/7)]. Знак t сокращается, так что предел двусторонний."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-17","topicId":21,"question":"Вариант 6 · №1. Вычисли limₓ→−₁ (x³+1)/(x³+3x+4), не используя эквивалентности.","options":["1/2","1/3","2","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"При x=−1 возникает 0/0. Разложим сумму кубов: x³+1=(x+1)(x²−x+1)."},{"title":"Шаг 2","text":"Знаменатель x³+3x+4 имеет корень −1 и раскладывается как (x+1)(x²−x+4)."},{"title":"Шаг 3","text":"При x≠−1 сокращаем x+1 и получаем (x²−x+1)/(x²−x+4)."},{"title":"Шаг 4","text":"При x=−1 числитель оставшейся дроби равен 1+1+1=3."},{"title":"Шаг 5","text":"Знаменатель равен 1+1+4=6≠0. Поэтому можно перейти к пределу подстановкой."},{"title":"Шаг 6","text":"Ответ равен 3/6=1/2. Точная факторизация заменяет применение эквивалентностей."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-18","topicId":28,"question":"Вариант 6 · №2. Вычисли limₓ→−∞ (∛(x³+2x²+x+1)−∛(x³−x²+3x−1)).","options":["1","−1","3","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Пусть a=∛(x³+2x²+x+1), b=∛(x³−x²+3x−1)."},{"title":"Шаг 2","text":"По разности кубов a−b=(a³−b³)/(a²+ab+b²)=(3x²−2x+2)/(a²+ab+b²)."},{"title":"Шаг 3","text":"При x→−∞ реальный кубический корень даёт a/x=∛(1+2/x+1/x²+1/x³)→1."},{"title":"Шаг 4","text":"Аналогично b/x=∛(1−1/x+3/x²−1/x³)→1."},{"title":"Шаг 5","text":"После деления на x² отношение равно (3−2/x+2/x²)/[(a/x)²+(a/x)(b/x)+(b/x)²]."},{"title":"Шаг 6","text":"Числитель стремится к 3, знаменатель к 3. Поэтому предел равен 1. Для кубических корней выносится x, а не |x|, что отличается от случая квадратных корней."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-19","topicId":21,"question":"Вариант 6 · №3. Вычисли limₓ→−₂ (√(2−x)+x)/(√(11+x)+1,5x), не используя эквивалентности.","options":["9/20","3/5","3/20","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Введём h=x+2→0. Тогда x=−2+h, а обе части исходной дроби при h=0 равны нулю."},{"title":"Шаг 2","text":"Числитель √(2−x)+x=√(4−h)−2+h=h·[1−1/(√(4−h)+2)]."},{"title":"Шаг 3","text":"Знаменатель √(11+x)+1,5x=√(9+h)−3+(3/2)h=h·[3/2+1/(√(9+h)+3)]."},{"title":"Шаг 4","text":"Оба равенства получены умножением разности корней на сопряжённое. При h≠0 сокращаем общий множитель h."},{"title":"Шаг 5","text":"Оставшееся отношение стремится к [1−1/4]/[3/2+1/6]=(3/4)/(5/3)."},{"title":"Шаг 6","text":"Деление даёт (3/4)·(3/5)=9/20. Основания корней близки к 4 и 9, поэтому в выбранной окрестности положительны."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-20","topicId":25,"question":"Вариант 6 · №4. Вычисли limₓ→₀₊ sin(11x+2√x)/tg(5x−3√x).","options":["−2/3","2/3","−3/2","не существует"],"correct":0,"steps":[{"title":"Шаг 1","text":"Из-за √x вещественная область требует x≥0, поэтому предел в нуле рассматривается справа."},{"title":"Шаг 2","text":"Положим t=√x→0⁺. Тогда x=t², u=11t²+2t=t(11t+2), v=5t²−3t=t(5t−3)."},{"title":"Шаг 3","text":"При достаточно малых t>0 имеем u≠0,v≠0, и тангенс определён."},{"title":"Шаг 4","text":"Пишем sin u/tg v=[sin u/u]·[v/tg v]·[(11t+2)/(5t−3)]."},{"title":"Шаг 5","text":"Первые два множителя стремятся к 1. Последний стремится к 2/(−3)=−2/3."},{"title":"Шаг 6","text":"Поэтому ответ −2/3. Знак отрицательный, потому что малый аргумент тангенса справа от нуля отрицателен."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-21","topicId":25,"question":"Вариант 6 · №5. Вычисли limₓ→π (cos 3x−cos 5x)/(π−x)², не используя эквивалентности.","options":["−8","8","−4","0"],"correct":0,"steps":[{"title":"Шаг 1","text":"Пусть h=x−π→0. Знаменатель (π−x)²=h²."},{"title":"Шаг 2","text":"Числитель cos(3π+3h)−cos(5π+5h)=−cos3h+cos5h."},{"title":"Шаг 3","text":"По формуле разности косинусов cos5h−cos3h=−2sin4h·sin h."},{"title":"Шаг 4","text":"Делим на h² и получаем −8·[sin4h/(4h)]·[sin h/h]."},{"title":"Шаг 5","text":"Каждое отношение стремится к 1, следовательно, предел равен −8."},{"title":"Шаг 6","text":"Квадрат знаменателя не меняет знак, поэтому знак ответа полностью определяется порядком косинусов в числителе."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-22","topicId":26,"question":"Вариант 6 · №6. Вычисли limₓ→∞ ((x²−5)/(x²+3))^(3x²−1).","options":["e⁻²⁴","e²⁴","e⁻⁸","1"],"correct":0,"steps":[{"title":"Шаг 1","text":"Основание (x²−5)/(x²+3) равно 1−8/(x²+3)."},{"title":"Шаг 2","text":"Положим u=−8/(x²+3)→0, p=3x²−1. При больших x основание положительно."},{"title":"Шаг 3","text":"Произведение pu=−8(3x²−1)/(x²+3) стремится к −24."},{"title":"Шаг 4","text":"Логарифм исходного выражения равен p ln(1+u)=pu·[ln(1+u)/u]."},{"title":"Шаг 5","text":"Второй множитель стремится к 1, поэтому логарифм стремится к −24."},{"title":"Шаг 6","text":"Возвращаемся экспонентой и получаем e⁻²⁴. Добавка к основанию отрицательна, что согласуется с пределом меньше 1."}],"source":"Нарешка · Подготовка к контрольной"},{"id":"legacy-kr-23","topicId":26,"question":"Вариант 6 · №7. Вычисли limₓ→₁ (x^1,7−1)/(3x²+2x−5), не используя эквивалентности.","options":["17/80","7/40","17/40","1/8"],"correct":0,"steps":[{"title":"Шаг 1","text":"Рассматриваем x в положительной окрестности 1, чтобы вещественная степень x^1,7 была определена."},{"title":"Шаг 2","text":"Знаменатель 3x²+2x−5=(x−1)(3x+5)."},{"title":"Шаг 3","text":"Положим t=x−1→0. Тогда числитель равен (1+t)^(17/10)−1."},{"title":"Шаг 4","text":"При x≠1 исходная дробь равна {[(1+t)^(17/10)−1]/t}·1/(3x+5)."},{"title":"Шаг 5","text":"По степенному следствию второго замечательного предела первая фигурная скобка стремится к 17/10, вторая — к 1/8."},{"title":"Шаг 6","text":"Поэтому предел равен (17/10)·(1/8)=17/80. Использован предел отношения, без замены исходных слагаемых эквивалентами и без производных."}],"source":"Нарешка · Подготовка к контрольной"}];

